"""Fused MXFP4 MoE in FlyDSL: for the token counts in ``_OWNED``, an owned pipeline (input quant and routing,
two block-scaled FP4 MFMA stages, stage 1 quantizing SiLU(gate)*up to MXFP4, a weighted top-k reduction into
``out``); otherwise aiter's FlyDSL two-stage pipeline, configured per token count in ``_plan``."""

import dataclasses
import functools

import flydsl.compiler as flyc
import flydsl.expr as fx
import torch
from flydsl._mlir import ir
from flydsl._mlir.dialects import llvm
from flydsl.expr import gpu, rocdl
from flydsl.expr.typing import ReductionOp, T
from flydsl.extension.coop.warp import warp_inclusive_scan, warp_reduce


def _sweep(name, default):
    # A named constant: the name records which tuned choice ``build_moe_module`` makes.
    return int(default)


def _sweep_bool(name, default):
    value = _sweep(name, int(default))
    if value not in (0, 1):
        raise ValueError(f"{name} must be 0 or 1")
    return value == 1


_DPP_SCAN = _sweep_bool("DPP_SCAN", True)
_DPP_INPUT = _sweep_bool("DPP_INPUT", True)


def _ptr(addr, dtype, alignment=4):
    return fx.inttoptr(fx.PointerType.get(dtype.ir_type, fx.AddressSpace.Global, alignment), fx.Int64(addr))


def _load(addr, offset, dtype=fx.Int32):
    if dtype == fx.Uint8:
        rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Uint8, 1)))
        return fx.Uint8(rocdl.raw_ptr_buffer_load(T.i8, rsrc, fx.Int32(offset), fx.Int32(0), 0))
    return fx.ptr_load(fx.add_offset(_ptr(addr, dtype, dtype.width // 8), offset))


def _store(addr, offset, value, dtype=fx.Int32):
    fx.ptr_store(dtype(value), fx.add_offset(_ptr(addr, dtype, dtype.width // 8), offset))


def _load4(addr, offset, CACHE=0):
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Int32, 16)))
    return fx.Vector(rocdl.raw_ptr_buffer_load(T.i32x4, rsrc, fx.Int32(offset) * 4, fx.Int32(0), CACHE))


def _load4_lds(addr, offset, destination):
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Int32, 16)))
    address = fx.Int32(fx.ptrtoint(destination))
    uniform = fx.Int32(rocdl.readfirstlane(T.i32, address))
    pointer = fx.inttoptr(fx.PointerType.get(fx.Int32.ir_type, fx.AddressSpace.Shared, 16), uniform)
    rocdl.raw_ptr_buffer_load_lds(
        rsrc, fx.to_llvm_ptr(pointer), fx.Int32(16), fx.Int32(offset) * 4, fx.Int32(0), fx.Int32(0), 0
    )


def _max(a, b):
    return (a > b).select(a, b)


def _input_max(a, b):
    if fx.const_expr(_DPP_INPUT):
        result = fx.Float32(fx.maxnumf(a, b))
    else:
        result = _max(a, b)
    return result


def _amax_reduce(a, steps, INPUT=False):
    # Nonnegative finite floats order like their unsigned bits, so the DPP subgroup max runs on integers.
    if fx.const_expr(INPUT and _DPP_INPUT):
        a = warp_reduce(a.bitcast(fx.Uint32), ReductionOp.MAX, width=1 << steps).bitcast(fx.Float32)
    else:
        for step in range(steps):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
    return a


def _epilogue_reduce(a, DPP):
    if fx.const_expr(DPP):
        a = warp_reduce(a.bitcast(fx.Uint32), ReductionOp.MAX, width=16).bitcast(fx.Float32)
    else:
        for step in range(4):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
    return a


def _prefix64(value, lane):
    if fx.const_expr(_DPP_SCAN):
        value = warp_inclusive_scan(value, ReductionOp.ADD, width=64)
    else:
        for step in range(6):
            left = fx.Int32(gpu.shuffle_up(value, 1 << step, 64))
            value = value + (lane >= (1 << step)).select(left, fx.Int32(0))
    return value


def _scale_offset(e, n, kg, N, K, ADDR_BITS):
    # Inverse of the stored scale permutation; with ADDR_BITS, power-of-two shapes map coordinates to address bits.
    if fx.const_expr(ADDR_BITS):
        offset = (
            e * N * (K // 32)
            + (n >> 5) * (K // 256) * 256
            + (kg >> 3) * 256
            + (kg & 3) * 64
            + (n & 15) * 4
            + ((kg >> 2) & 1) * 2
            + ((n >> 4) & 1)
        )
    else:
        offset = (
            e * N * (K // 32)
            + (n // 32) * (K // 256) * 256
            + (kg // 8) * 256
            + (kg % 4) * 64
            + (n % 16) * 4
            + (kg % 8 // 4) * 2
            + (n % 32 // 16)
        )
    return offset


def _weight_offset(e, n, kg, N, K, ADDR_BITS):
    # One lane's 16 bytes of a weight row; with ADDR_BITS the two interleaved K halves share one stride.
    if fx.const_expr(ADDR_BITS):
        offset = e * N * (K // 8) + (n >> 4) * (K // 8) * 16 + kg * 64 + (n & 15) * 4
    else:
        offset = e * N * (K // 8) + (n // 16) * (K // 8) * 16 + (kg // 2) * 128 + (kg % 2) * 64 + (n % 16) * 4
    return offset


def _mfma(a, b, c, sa, sb):
    return fx.Vector(rocdl.mfma_scale_f32_16x16x128_f8f6f4(T.f32x4, [a, b, c, 4, 4, 0, sa, 0, sb]))


def _mfma_sel(a, b, c, sa, sb, sel_b):
    return fx.Vector(rocdl.mfma_scale_f32_16x16x128_f8f6f4(T.f32x4, [a, b, c, 4, 4, 0, sa, sel_b, sb]))


def _mfma_sel2(a, b, c, sa, sel_a, sb, sel_b):
    return fx.Vector(rocdl.mfma_scale_f32_16x16x128_f8f6f4(T.f32x4, [a, b, c, 4, 4, sel_a, sa, sel_b, sb]))


def _mfma2(a, b, c, sa, sb, WIDE):
    if fx.const_expr(WIDE):
        return fx.Vector(
            rocdl.mfma_scale_f32_32x32x64_f8f6f4(
                fx.Vector.make_type(16, fx.Float32), [a, b, c, 4, 4, 0, sa, 0, sb]
            )
        )
    else:
        return _mfma(a, b, c, sa, sb)


def _silu_bf16(g, u):
    exp_neg = fx.Float32(rocdl.exp2(T.f32, (-g * fx.Float32(1.4426950408889634)).ir_value()))
    inv = fx.Float32(rocdl.rcp(T.f32, (fx.Float32(1.0) + exp_neg).ir_value()))
    return fx.Float32(fx.BFloat16((g * inv) * u))


def _chiplet_order(pid, bound):
    chiplet = pid % 8
    quotient, remainder = bound // 8, bound % 8
    return chiplet * quotient + (chiplet < remainder).select(chiplet, remainder) + pid // 8


def _routed_row(Routes, offset, tile, DIRECT):
    rid = tile
    if fx.const_expr(not DIRECT):
        rid = _load(Routes, offset)
    return rid


def _w1_operands(W, WS, e, nbase, wave, lane, kg, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED):
    result = []
    for ni in range(BN // (WAVES * 16)):
        n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
        result.extend(
            [
                _load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE),
                _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE),
                _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED),
                _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED),
            ]
        )
    return result


def _w1_words(WS, e, n0, lane, kk, I, D):
    # The gate and up packed scale words of one K step (even kk): slice ki, column fragment ni takes byte ki*2 + ni.
    kg = kk * 4 + lane // 16
    return [
        _load(
            WS,
            e * (2 * I) * (D // 128) + (n >> 5) * (D // 256) * 64 + (kg >> 3) * 64 + (kg & 3) * 16 + (n & 15),
        )
        for n in (n0, n0 + I)
    ]


def _w1_slice(W, e, n0, lane, k, I, D, NR, ADDR_BITS, CACHE):
    # One K slice's gate and up weight fragments, per 16-column fragment ni: [gate0, up0, gate1, up1, ...].
    kg = k * 4 + lane // 16
    data = []
    for ni in range(NR):
        data.append(_load4(W, _weight_offset(e, n0 + ni * 16, kg, 2 * I, D, ADDR_BITS), CACHE))
        data.append(_load4(W, _weight_offset(e, n0 + ni * 16 + I, kg, 2 * I, D, ADDR_BITS), CACHE))
    return data


def _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED):
    if fx.const_expr(PACKED):
        # Each word holds two 16-column halves of two adjacent K slices.
        offset = e * D * (I // 128) + (n >> 5) * (I // 256) * 64 + (kg >> 3) * 64 + (kg & 3) * 16 + (n & 15)
        word = _load(WS, offset)
        shift = (((kg >> 2) & 1) * 2 + ((n >> 4) & 1)) * 8
        scale = (word >> shift) & 255
    else:
        scale = fx.Int32(_load(WS, _scale_offset(e, n, kg, D, I, ADDR_BITS), fx.Uint8))
    return scale


def _w2_operands(W, WS, e, nbase, wave, lane, kg, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED):
    result = []
    for ni in range(BN // (FRAG * 4)):
        n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
        result.extend(
            [
                _load4(W, _weight_offset(e, n, kg, D, I, ADDR_BITS), CACHE),
                _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED),
            ]
        )
    return result


@flyc.kernel
def _quantize(
    X: fx.Int64,
    Q: fx.Int64,
    S: fx.Int64,
    Counts: fx.Int64,
    TOTAL: fx.Constexpr[int],
    E: fx.Constexpr[int],
    CLEAR: fx.Constexpr[bool],
):
    t = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if fx.const_expr(CLEAR):
        if t < E:
            _store(Counts, t, 0)
    if t < TOTAL // 2:
        x0 = fx.Float32(_load(X, t * 2, fx.BFloat16))
        x1 = fx.Float32(_load(X, t * 2 + 1, fx.BFloat16))
        a = _input_max(fx.absf(x0), fx.absf(x1))
        a = _amax_reduce(a, 4, True)
        a = _input_max(a, fx.Float32(1.0e-10))
        # Exact frexp(a).exponent - 3 + (mantissa > .75), no division.
        bits = a.bitcast(fx.Int32)
        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
        scale = (exponent << 23).bitcast(fx.Float32)
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
        _store(Q, t, packed, fx.Uint8)
        if t % 16 == 0:
            _store(S, t // 16, exponent, fx.Uint8)


@flyc.kernel
def _route(Ids: fx.Int64, Counts: fx.Int64, Routes: fx.Int64, R: fx.Constexpr[int]):
    tid = fx.Int32(fx.thread_idx.x)
    lane = tid % 64
    r = fx.Int32(fx.block_idx.x) * 256 + tid
    e = fx.Int32(fx.block_idx.y)
    match = fx.Boolean(False)
    if r < R:
        match = _load(Ids, r) == e
    mask = fx.Uint64(rocdl.ballot(T.i64, match))
    count = fx.Int32(fx.ctpop(mask))
    rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
    base = fx.Int32(0)
    if lane == 0:
        p = fx.to_llvm_ptr(fx.add_offset(_ptr(Counts, fx.Int32), e))
        base = fx.Int32(
            llvm.atomicrmw(llvm.AtomicBinOp.add, p, count.ir_value(), llvm.AtomicOrdering.monotonic)
        )
    base = fx.Int32(gpu.shuffle_idx(base, 0, 64))
    if match:
        _store(Routes, e * R + base + rank, r)


@flyc.kernel
def _route_block(Ids: fx.Int64, Counts: fx.Int64, Routes: fx.Int64, R: fx.Constexpr[int]):
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    r = fx.Int32(fx.block_idx.x) * 256 + tid
    e = fx.Int32(fx.block_idx.y)
    offsets = fx.recast_iter(fx.Int32, fx.SharedAllocator().allocate(16, alignment=16).peek().ptr)
    match = fx.Boolean(False)
    if r < R:
        match = _load(Ids, r) == e
    mask = fx.Uint64(rocdl.ballot(T.i64, match))
    count = fx.Int32(fx.ctpop(mask))
    rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
    if lane == 0:
        fx.ptr_store(count, fx.add_offset(offsets, wave))
    gpu.barrier()
    if tid == 0:
        c0 = fx.Int32(fx.ptr_load(offsets))
        c1 = fx.Int32(fx.ptr_load(fx.add_offset(offsets, 1)))
        c2 = fx.Int32(fx.ptr_load(fx.add_offset(offsets, 2)))
        c3 = fx.Int32(fx.ptr_load(fx.add_offset(offsets, 3)))
        total = c0 + c1 + c2 + c3
        base = fx.Int32(0)
        if total > 0:
            p = fx.to_llvm_ptr(fx.add_offset(_ptr(Counts, fx.Int32), e))
            base = fx.Int32(
                llvm.atomicrmw(llvm.AtomicBinOp.add, p, total.ir_value(), llvm.AtomicOrdering.monotonic)
            )
        fx.ptr_store(base, offsets)
        fx.ptr_store(base + c0, fx.add_offset(offsets, 1))
        fx.ptr_store(base + c0 + c1, fx.add_offset(offsets, 2))
        fx.ptr_store(base + c0 + c1 + c2, fx.add_offset(offsets, 3))
    gpu.barrier()
    base = fx.Int32(fx.ptr_load(fx.add_offset(offsets, wave)))
    if match:
        _store(Routes, e * R + base + rank, r)


def _quantize_eight(X, t):
    return _quantize_eight_values(_load4(X, t * 4))


def _quantize_eight_values(raw):
    packed_input = raw.bitcast(fx.BFloat16)
    values = [fx.Float32(packed_input[j]) for j in range(8)]
    a = fx.absf(values[0])
    for j in range(1, 8):
        a = _input_max(a, fx.absf(values[j]))
    a = _amax_reduce(a, 2, True)
    a = _input_max(a, fx.Float32(1.0e-10))
    bits = a.bitcast(fx.Int32)
    exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
    scale = (exponent << 23).bitcast(fx.Float32)
    packed = fx.Int32(0)
    for j in range(4):
        packed = fx.Int32(
            rocdl.cvt_scalef32_pk_fp4_f32(T.i32, packed, values[j * 2], values[j * 2 + 1], scale, j)
        )
    return packed, exponent


@flyc.kernel
def _route_expert(
    Ids: fx.Int64,
    Counts: fx.Int64,
    Routes: fx.Int64,
    R: fx.Constexpr[int],
    WAVES: fx.Constexpr[int],
    X: fx.Int64,
    Q: fx.Int64,
    S: fx.Int64,
    SIZE: fx.Constexpr[int],
    E: fx.Constexpr[int],
    QUANT: fx.Constexpr[bool],
    VEC: fx.Constexpr[bool],
    TWO_PASS: fx.Constexpr[bool],
    UNROLL_SCAN: fx.Constexpr[bool],
    QUNROLL: fx.Constexpr[int],
):
    # Each workgroup owns an expert and compacts its routes in input order.
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    e = fx.Int32(fx.block_idx.x)
    shared = fx.recast_iter(fx.Int32, fx.SharedAllocator().allocate(WAVES * 8, alignment=16).peek().ptr)
    if fx.const_expr(QUANT and QUNROLL > 0):
        # The first E workgroups only scan; each later thread issues all QUNROLL input loads before converting.
        assert VEC and (SIZE // 8) % (WAVES * 64 * QUNROLL) == 0
        if e >= E:
            base_t = (e - E) * (WAVES * 64 * QUNROLL) + tid
            raws = [_load4(X, (base_t + u * (WAVES * 64)) * 4) for u in fx.range_constexpr(QUNROLL)]
            for u in fx.range_constexpr(QUNROLL):
                t = base_t + u * (WAVES * 64)
                packed, exponent = _quantize_eight_values(raws[u])
                _store(Q, t, packed)
                if t % 4 == 0:
                    _store(S, t // 4, exponent, fx.Uint8)
    elif fx.const_expr(QUANT):
        # Quantization fills the grid; the first E workgroups also run the independent expert scans.
        t = e * (WAVES * 64) + tid
        if fx.const_expr(VEC):
            if t < SIZE // 8:
                packed, exponent = _quantize_eight(X, t)
                _store(Q, t, packed)
                if t % 4 == 0:
                    _store(S, t // 4, exponent, fx.Uint8)
        elif t < SIZE // 2:
            x0 = fx.Float32(_load(X, t * 2, fx.BFloat16))
            x1 = fx.Float32(_load(X, t * 2 + 1, fx.BFloat16))
            a = _input_max(fx.absf(x0), fx.absf(x1))
            a = _amax_reduce(a, 4, True)
            a = _input_max(a, fx.Float32(1.0e-10))
            bits = a.bitcast(fx.Int32)
            exponent = (
                ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
            )
            scale = (exponent << 23).bitcast(fx.Float32)
            packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
            _store(Q, t, packed, fx.Uint8)
            if t % 16 == 0:
                _store(S, t // 16, exponent, fx.Uint8)
    if fx.const_expr(not QUANT) or e < E:
        if fx.const_expr(TWO_PASS and UNROLL_SCAN):
            # Each wave counts a contiguous input segment, then writes it after one shared prefix scan; both passes
            # are unrolled, so all of a segment's id loads are in flight and the second pass reuses the match masks.
            CHUNKS = (R + WAVES * 64 - 1) // (WAVES * 64)
            masks = []
            seg = fx.Int32(0)
            for chunk in fx.range_constexpr(CHUNKS):
                r = (wave * CHUNKS + chunk) * 64 + lane
                if fx.const_expr(R % (WAVES * 64) == 0):
                    match = _load(Ids, r) == e
                else:
                    match = (r < R) & (_load(Ids, (r < R).select(r, fx.Int32(0))) == e)
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                masks.append((r, match, mask))
                seg = seg + fx.Int32(fx.ctpop(mask))
            if lane == 0:
                fx.ptr_store(seg, fx.add_offset(shared, wave))
            gpu.barrier()
            if wave == 0:
                prefix = fx.Int32(0)
                if lane < WAVES:
                    prefix = fx.Int32(fx.ptr_load(fx.add_offset(shared, lane)))
                prefix = _prefix64(prefix, lane)
                if lane < WAVES:
                    fx.ptr_store(prefix, fx.add_offset(shared, lane))
            gpu.barrier()
            if tid == 0:
                _store(Counts, e, fx.Int32(fx.ptr_load(fx.add_offset(shared, WAVES - 1))))
            position = fx.Int32(0)
            if wave > 0:
                position = fx.Int32(fx.ptr_load(fx.add_offset(shared, wave - 1)))
            below = (fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1)
            for r, match, mask in masks:
                rank = fx.Int32(fx.ctpop(mask & below))
                if match:
                    _store(Routes, e * R + position + rank, r)
                position = position + fx.Int32(fx.ctpop(mask))
        elif fx.const_expr(TWO_PASS):
            CHUNKS = (R + WAVES * 64 - 1) // (WAVES * 64)
            for chunk, state in range(0, CHUNKS, 1, init=[fx.Int32(0)]):
                r = (wave * CHUNKS + fx.Int32(chunk)) * 64 + lane
                match = fx.Boolean(False)
                if r < R:
                    match = _load(Ids, r) == e
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                result = yield [fx.Int32(state[0]) + fx.Int32(fx.ctpop(mask))]
            if lane == 0:
                fx.ptr_store(result, fx.add_offset(shared, wave))
            gpu.barrier()
            if wave == 0:
                prefix = fx.Int32(0)
                if lane < WAVES:
                    prefix = fx.Int32(fx.ptr_load(fx.add_offset(shared, lane)))
                prefix = _prefix64(prefix, lane)
                if lane < WAVES:
                    fx.ptr_store(prefix, fx.add_offset(shared, lane))
            gpu.barrier()
            if tid == 0:
                _store(Counts, e, fx.Int32(fx.ptr_load(fx.add_offset(shared, WAVES - 1))))
            base = fx.Int32(0)
            if wave > 0:
                base = fx.Int32(fx.ptr_load(fx.add_offset(shared, wave - 1)))
            for chunk, state in range(0, CHUNKS, 1, init=[base]):
                r = (wave * CHUNKS + fx.Int32(chunk)) * 64 + lane
                match = fx.Boolean(False)
                if r < R:
                    match = _load(Ids, r) == e
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
                if match:
                    _store(Routes, e * R + fx.Int32(state[0]) + rank, r)
                result = yield [fx.Int32(state[0]) + fx.Int32(fx.ctpop(mask))]
        else:
            for chunk, state in range(0, (R + WAVES * 64 - 1) // (WAVES * 64), 1, init=[fx.Int32(0)]):
                total = fx.Int32(state[0])
                r = fx.Int32(chunk) * (WAVES * 64) + tid
                match = fx.Boolean(False)
                if r < R:
                    match = _load(Ids, r) == e
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                count = fx.Int32(fx.ctpop(mask))
                rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
                # Alternate scan buffers while other waves consume earlier offsets.
                buf = (fx.Int32(chunk) & 1) * WAVES
                if lane == 0:
                    fx.ptr_store(count, fx.add_offset(shared, buf + wave))
                gpu.barrier()
                if wave == 0:
                    prefix = fx.Int32(0)
                    if lane < WAVES:
                        prefix = fx.Int32(fx.ptr_load(fx.add_offset(shared, buf + lane)))
                    prefix = _prefix64(prefix, lane)
                    if lane < WAVES:
                        fx.ptr_store(prefix, fx.add_offset(shared, buf + lane))
                gpu.barrier()
                offset = fx.Int32(0)
                if wave > 0:
                    offset = fx.Int32(fx.ptr_load(fx.add_offset(shared, buf + wave - 1)))
                if match:
                    _store(Routes, e * R + total + offset + rank, r)
                increment = fx.Int32(fx.ptr_load(fx.add_offset(shared, buf + WAVES - 1)))
                result = yield [total + increment]
            if tid == 0:
                _store(Counts, e, result)


@flyc.kernel
def _route_fused(
    Ids: fx.Int64,
    Counts: fx.Int64,
    Routes: fx.Int64,
    TileE: fx.Int64,
    TileR: fx.Int64,
    Total: fx.Int64,
    R: fx.Constexpr[int],
    E: fx.Constexpr[int],
    BM: fx.Constexpr[int],
    WAVES: fx.Constexpr[int],
):
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    shared = fx.recast_iter(fx.Int32, fx.SharedAllocator().allocate(E * 4, alignment=16).peek().ptr)
    # Each wave owns an expert at a time, so its routes and count need no atomics.
    for group in fx.range_constexpr((E + WAVES - 1) // WAVES):
        e = group * WAVES + wave
        count = fx.Int32(0)
        for chunk in fx.range_constexpr((R + 63) // 64):
            r = chunk * 64 + lane
            match = fx.Boolean(False)
            if e < E and r < R:
                match = _load(Ids, r) == e
            mask = fx.Uint64(rocdl.ballot(T.i64, match))
            rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
            if match:
                _store(Routes, e * R + count + rank, r)
            count = count + fx.Int32(fx.ctpop(mask))
        if e < E and lane == 0:
            _store(Counts, e, count)
            fx.ptr_store(count, fx.add_offset(shared, e))
    gpu.barrier()
    if tid < 64:
        cnt = fx.Int32(0)
        if tid < E:
            cnt = (fx.Int32(fx.ptr_load(fx.add_offset(shared, tid))) + BM - 1) // BM
        prefix = cnt
        prefix = _prefix64(prefix, tid)
        if tid == 63:
            _store(Total, 0, prefix)
        for j in range(cnt):
            _store(TileE, prefix - cnt + fx.Int32(j), tid)
            _store(TileR, prefix - cnt + fx.Int32(j), fx.Int32(j) * BM)


@flyc.kernel
def _quantize_route_fused(
    X: fx.Int64,
    Q: fx.Int64,
    S: fx.Int64,
    Ids: fx.Int64,
    Counts: fx.Int64,
    Routes: fx.Int64,
    TileE: fx.Int64,
    TileR: fx.Int64,
    Total: fx.Int64,
    SIZE: fx.Constexpr[int],
    R: fx.Constexpr[int],
    E: fx.Constexpr[int],
    BM: fx.Constexpr[int],
    WAVES: fx.Constexpr[int],
):
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    t = fx.Int32(fx.block_idx.x) * (WAVES * 64) + tid
    shared = fx.recast_iter(fx.Int32, fx.SharedAllocator().allocate(E * 4, alignment=16).peek().ptr)
    if t < SIZE // 2:
        x0 = fx.Float32(_load(X, t * 2, fx.BFloat16))
        x1 = fx.Float32(_load(X, t * 2 + 1, fx.BFloat16))
        a = _input_max(fx.absf(x0), fx.absf(x1))
        a = _amax_reduce(a, 4, True)
        a = _input_max(a, fx.Float32(1.0e-10))
        bits = a.bitcast(fx.Int32)
        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
        scale = (exponent << 23).bitcast(fx.Float32)
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
        _store(Q, t, packed, fx.Uint8)
        if t % 16 == 0:
            _store(S, t // 16, exponent, fx.Uint8)
    if fx.Int32(fx.block_idx.x) == 0:
        for group in fx.range_constexpr((E + WAVES - 1) // WAVES):
            e = group * WAVES + wave
            count = fx.Int32(0)
            for chunk in fx.range_constexpr((R + 63) // 64):
                r = chunk * 64 + lane
                match = fx.Boolean(False)
                if e < E and r < R:
                    match = _load(Ids, r) == e
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
                if match:
                    _store(Routes, e * R + count + rank, r)
                count = count + fx.Int32(fx.ctpop(mask))
            if e < E and lane == 0:
                _store(Counts, e, count)
                fx.ptr_store(count, fx.add_offset(shared, e))
        gpu.barrier()
        if tid < 64:
            cnt = fx.Int32(0)
            if tid < E:
                cnt = (fx.Int32(fx.ptr_load(fx.add_offset(shared, tid))) + BM - 1) // BM
            prefix = cnt
            prefix = _prefix64(prefix, tid)
            if tid == 63:
                _store(Total, 0, prefix)
            for j in range(cnt):
                _store(TileE, prefix - cnt + fx.Int32(j), tid)
                _store(TileR, prefix - cnt + fx.Int32(j), fx.Int32(j) * BM)


@flyc.kernel
def _route_tiles(
    Counts: fx.Int64,
    TileE: fx.Int64,
    TileR: fx.Int64,
    Total: fx.Int64,
    E: fx.Constexpr[int],
    BM: fx.Constexpr[int],
):
    # Lane l owns experts l and l + 64, in that order.
    e = fx.Int32(fx.thread_idx.x)
    cnt = fx.Int32(0)
    if e < E:
        cnt = (_load(Counts, e) + BM - 1) // BM
    cnt_hi = fx.Int32(0)
    if fx.const_expr(E > 64):
        if e + 64 < E:
            cnt_hi = (_load(Counts, e + 64) + BM - 1) // BM
    both = cnt + cnt_hi
    prefix = _prefix64(both, e)
    if e == 63:
        _store(Total, 0, prefix)
    start = prefix - both
    for j in range(cnt):
        _store(TileE, start + fx.Int32(j), e)
        _store(TileR, start + fx.Int32(j), fx.Int32(j) * BM)
    if fx.const_expr(E > 64):
        for j in range(cnt_hi):
            _store(TileE, start + cnt + fx.Int32(j), e + 64)
            _store(TileR, start + cnt + fx.Int32(j), fx.Int32(j) * BM)


def _map_expert_tile(Counts, tile, lane, E, BM):
    index = (lane < E).select(lane, fx.Int32(0))
    count = _load(Counts, index)
    tiles = (lane < E).select((count + BM - 1) // BM, fx.Int32(0))
    tiles_hi = fx.Int32(0)
    if fx.const_expr(E > 64):
        index_hi = (lane + 64 < E).select(lane + 64, fx.Int32(0))
        count_hi = _load(Counts, index_hi)
        tiles_hi = (lane + 64 < E).select((count_hi + BM - 1) // BM, fx.Int32(0))
    both = tiles + tiles_hi
    prefix = _prefix64(both, lane)
    total = fx.Int32(gpu.shuffle_idx(prefix, 63, 64))
    mask = fx.Uint64(rocdl.ballot(T.i64, prefix > tile))
    owner = fx.Int32(64) - fx.Int32(fx.ctpop(mask))
    owner = (tile < total).select(owner, fx.Int32(0))
    end = fx.Int32(gpu.shuffle_idx(prefix, owner, 64))
    length = fx.Int32(gpu.shuffle_idx(both, owner, 64))
    low = fx.Int32(gpu.shuffle_idx(tiles, owner, 64))
    local = tile - end + length
    hi = local >= low
    expert = hi.select(owner + 64, owner)
    local = hi.select(local - low, local)
    return total, expert, local * BM


def _derive_tile(Counts, pid, lane, NB, E, BM):
    # Each wave derives its workgroup's tile from the expert counts in ``_route_tiles``' order: returns the launch
    # bound, the chiplet-ordered index, the tile, its expert, first row and route count, all wave-uniform.
    index = (lane < E).select(lane, fx.Int32(0))
    count = _load(Counts, index)
    tiles = (lane < E).select((count + BM - 1) // BM, fx.Int32(0))
    count_hi, tiles_hi = fx.Int32(0), fx.Int32(0)
    if fx.const_expr(E > 64):
        index_hi = (lane + 64 < E).select(lane + 64, fx.Int32(0))
        count_hi = _load(Counts, index_hi)
        tiles_hi = (lane + 64 < E).select((count_hi + BM - 1) // BM, fx.Int32(0))
    both = tiles + tiles_hi
    prefix = _prefix64(both, lane)
    total = fx.Int32(rocdl.readlane(T.i32, prefix, fx.Int32(63)))
    bound = total * NB
    ordered = _chiplet_order(pid, bound)
    tile = ordered // NB
    mask = fx.Uint64(rocdl.ballot(T.i64, prefix > tile))
    owner = fx.Int32(64) - fx.Int32(fx.ctpop(mask))
    owner = fx.Int32(rocdl.readfirstlane(T.i32, (tile < total).select(owner, fx.Int32(0))))
    end = fx.Int32(rocdl.readlane(T.i32, prefix, owner))
    length = fx.Int32(rocdl.readlane(T.i32, both, owner))
    low = fx.Int32(rocdl.readlane(T.i32, tiles, owner))
    c_lo = fx.Int32(rocdl.readlane(T.i32, count, owner))
    c_hi = fx.Int32(rocdl.readlane(T.i32, count_hi, owner))
    local = tile - end + length
    hi = local >= low
    expert = hi.select(owner + 64, owner)
    local = hi.select(local - low, local)
    return bound, ordered, tile, expert, local * BM, hi.select(c_hi, c_lo), (prefix, tiles, tiles_hi)


@flyc.kernel
def _gather_quant(
    A: fx.Int64,
    AS: fx.Int64,
    B: fx.Int64,
    BS: fx.Int64,
    Routes: fx.Int64,
    Counts: fx.Int64,
    TE: fx.Int64,
    TR: fx.Int64,
    Total: fx.Int64,
    R: fx.Constexpr[int],
    K: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
    BM: fx.Constexpr[int],
    ROW_PAD: fx.Constexpr[int],
    E: fx.Constexpr[int],
    MAP_TILES: fx.Constexpr[bool],
):
    tile = fx.Int32(fx.block_idx.y)
    t = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if fx.const_expr(MAP_TILES):
        total, expert, first_row = _map_expert_tile(Counts, tile, fx.Int32(fx.thread_idx.x) % 64, E, BM)
        if t == 0:
            if tile == 0:
                _store(Total, 0, total)
            if tile < total:
                _store(TE, tile, expert)
                _store(TR, tile, first_row)
    else:
        total = _load(Total, 0)
    if tile < total:
        if t < BM * (K // 32):
            row, kg = t % BM, t // BM
            if fx.const_expr(MAP_TILES):
                e, rr = expert, first_row + row
            else:
                e = _load(TE, tile)
                rr = _load(TR, tile) + row
            rid = fx.Int32(0)
            if rr < _load(Counts, e):
                rid = _load(Routes, e * R + rr)
            src = rid // TOPK
            v = _load4(A, src * (K // 8) + kg * 4)
            dst = (tile * (K // 32) + kg) * (BM + ROW_PAD) + row
            fx.ptr_store(v, fx.add_offset(_ptr(B, fx.Int32, 16), dst * 4))
            scale = _load(AS, src * (K // 32) + kg, fx.Uint8)
            _store(BS, dst, scale, fx.Uint8)


@flyc.kernel
def _gather_quant_coalesced(
    A: fx.Int64,
    AS: fx.Int64,
    B: fx.Int64,
    BS: fx.Int64,
    Routes: fx.Int64,
    Counts: fx.Int64,
    TE: fx.Int64,
    TR: fx.Int64,
    Total: fx.Int64,
    R: fx.Constexpr[int],
    K: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
    BM: fx.Constexpr[int],
    ROW_PAD: fx.Constexpr[int],
    E: fx.Constexpr[int],
    MAP_TILES: fx.Constexpr[bool],
):
    # Read eight contiguous scale groups per routed row, then transpose them in LDS to the group-major layout.
    tile = fx.Int32(fx.block_idx.y)
    block = fx.Int32(fx.block_idx.x)
    tid = fx.Int32(fx.thread_idx.x)
    rbase = (block % (BM // 32)) * 32
    kbase = (block // (BM // 32)) * 8
    smem = fx.SharedAllocator()
    values = fx.recast_iter(fx.Int32, smem.allocate(256 * 16, alignment=16).peek().ptr)
    scales = fx.recast_iter(fx.Uint8, smem.allocate(256, alignment=16).peek().ptr)
    if fx.const_expr(MAP_TILES):
        total, expert, first_row = _map_expert_tile(Counts, tile, tid % 64, E, BM)
        if block == 0 and tid == 0:
            if tile == 0:
                _store(Total, 0, total)
            if tile < total:
                _store(TE, tile, expert)
                _store(TR, tile, first_row)
    else:
        total = _load(Total, 0)
    if tile < total:
        row, kg = tid // 8, tid % 8
        if fx.const_expr(MAP_TILES):
            e, rr = expert, first_row + rbase + row
        else:
            e = _load(TE, tile)
            rr = _load(TR, tile) + rbase + row
        rid = fx.Int32(0)
        if rr < _load(Counts, e):
            rid = _load(Routes, e * R + rr)
        src = rid // TOPK
        v = _load4(A, src * (K // 8) + (kbase + kg) * 4)
        scale = _load(AS, src * (K // 32) + kbase + kg, fx.Uint8)
        # The row-dependent XOR spreads the transposed 16-byte reads over all LDS banks.
        index = row * 8 + (kg ^ ((row // 2) % 8))
        fx.ptr_store(v, fx.add_offset(values, index * 4))
        fx.ptr_store(scale, fx.add_offset(scales, index))
        gpu.barrier()
        row, kg = tid % 32, tid // 32
        index = row * 8 + (kg ^ ((row // 2) % 8))
        v = fx.ptr_load(fx.add_offset(values, index * 4), result_type=T.i32x4)
        scale = fx.Uint8(fx.ptr_load(fx.add_offset(scales, index)))
        dst = (tile * (K // 32) + kbase + kg) * (BM + ROW_PAD) + rbase + row
        fx.ptr_store(v, fx.add_offset(_ptr(B, fx.Int32, 16), dst * 4))
        _store(BS, dst, scale, fx.Uint8)


# Scheduling fences keep the next panel's loads after the slice's weights and its LDS writes after the last MFMA.
PIPE_SCHED = True
# The K slice (1-based) whose start issues the next activation panel's loads.
PIPE1_AT = 2
# A fused fill copies the next panel straight into LDS a full K step ahead, and stage 1 rotates its weight registers.
PIPE1_DMA = True
# Revision tags of the stage-1 and stage-2 kernel bodies, passed to them as compile-time arguments. FlyDSL's cache
# key follows the launcher's source text, not a kernel body: clear the runtime cache after editing a body.
_GEMM1_REV = 3
_GEMM2_REV = 10


def _load_a_panel(A, AS, tile, kk, tid, D, BM, KSTEP, THREADS, ROW_PAD):
    result = []
    for cp in range((BM * 4 * KSTEP + THREADS - 1) // THREADS):
        ix = tid + cp * THREADS
        if fx.const_expr(ROW_PAD != 0):
            gi = (tile * (D // 32) + kk * 4 + ix // BM) * (BM + ROW_PAD) + ix % BM
        else:
            gi = (tile * (D // 32) + kk * 4) * BM + ix
        result.append((ix, _load4(A, gi * 4), fx.Int32(_load(AS, gi, fx.Uint8))))
    return result


def _routed_source(Routes, e, rb, count, row, R, TOPK, PAD=0):
    # Source token of one tile row; a padded row reads token PAD (0: the first token).
    r = rb + row
    valid = r < count
    return valid.select(_load(Routes, e * R + valid.select(r, fx.Int32(0))) // TOPK, fx.Int32(PAD))


def _a_panel_sources(Routes, e, rb, count, tid, R, D, TOPK, BM, KSTEP, THREADS, PAD=0):
    # Each thread's (LDS slot, byte offset of the row's first group): eight consecutive lanes take eight rows'
    # distinct scale groups, so each copy reads whole source lines and stores to distinct LDS banks.
    assert 4 * KSTEP == 8 and THREADS == 256 and BM % 32 == 0
    lane, wave = tid % 64, tid // 64
    kgl = (lane // 8 + lane % 8) % 8
    result = []
    for cp in range(BM * 4 * KSTEP // THREADS):
        row = lane % 8 + wave * 8 + cp * (THREADS // 8)
        # With PAD one past the last token, a padded row's copies fall outside the input's bounded buffer and land
        # as zeros, so the padded rows' MFMAs (and the zero intermediate rows they produce) switch no operand bits.
        src = _routed_source(Routes, e, rb, count, row, R, TOPK, PAD)
        result.append((kgl * BM + row, (src * (D // 32) + kgl) * 16))
    return result


def _load_a_panel_fused(A, sources, kk):
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(A, fx.Int32, 16)))
    k = fx.Int32(kk)
    return [
        (ix, fx.Vector(rocdl.raw_ptr_buffer_load(T.i32x4, rsrc, fx.Int32(off), k * 64, 0)), None)
        for ix, off in sources
    ]


def _dma_a_panel(rsrc, sources, kk, shared, base, wave):
    # Copy the K step's panel straight into LDS: lane l of copy cp lands in 16-byte slot cp*THREADS + wave*64 + l.
    soff = fx.Int32(kk) * 64
    for cp, (_, off) in enumerate(sources):
        address = fx.Int32(fx.ptrtoint(fx.add_offset(shared, base + (wave * 64 + cp * 256) * 4)))
        uniform = fx.Int32(rocdl.readfirstlane(T.i32, address))
        pointer = fx.inttoptr(fx.PointerType.get(fx.Int32.ir_type, fx.AddressSpace.Shared, 16), uniform)
        rocdl.raw_ptr_buffer_load_lds(
            rsrc, fx.to_llvm_ptr(pointer), fx.Int32(16), fx.Int32(off), soff, fx.Int32(0), 0
        )


# LDS reads of a buffer the in-flight copies do not target: with a scope, the backend inserts no wait for those
# copies; the loop's own counted vmcnt and barrier order every read after the copy that filled its buffer.
_LDS_READ_SCOPE = (
    "[#llvm.alias_scope<id = distinct[0]<>, domain = "
    '#llvm.alias_scope_domain<id = distinct[1]<>, description = "lds_read">>]'
)


def _lds_read(ptr, ty, alignment):
    scopes = ir.Attribute.parse(_LDS_READ_SCOPE)
    return llvm.load(ty, fx.to_llvm_ptr(ptr), alignment=alignment, alias_scopes=scopes)


def _load_scale_table(AS, Routes, e, rb, count, tid, R, D, TOPK, BM, THREADS, SROW):
    parts = D // 32 // 16
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(AS, fx.Int32, 16)))
    result = []
    n = BM * parts
    for cp in range((n + THREADS - 1) // THREADS):
        c = tid + cp * THREADS
        if (cp + 1) * THREADS > n:
            # Surplus threads repeat an earlier chunk: the same bytes to the same slot.
            c = (c < n).select(c, c - n)
        row, part = c // parts, c % parts
        src = _routed_source(Routes, e, rb, count, row, R, TOPK)
        v = fx.Vector(rocdl.raw_ptr_buffer_load(T.i32x4, rsrc, (src * parts + part) * 16, fx.Int32(0), 0))
        result.append(((row * SROW + part * 16) // 4, v))
    return result


def _store_scale_table(swords, table):
    for ti, tv in table:
        fx.ptr_store(tv, fx.add_offset(swords, ti))


def _store_a_panel(shared, base, panel, BM, KSTEP):
    for ix, vv, ss in panel:
        fx.ptr_store(vv, fx.add_offset(shared, base + ix * 4))
        if ss is not None:
            fx.ptr_store(ss, fx.add_offset(shared, base + BM * 16 * KSTEP + ix))


@flyc.kernel
def _gemm1(
    A: fx.Int64,
    AS: fx.Int64,
    W: fx.Int64,
    WS: fx.Int64,
    Routes: fx.Int64,
    Counts: fx.Int64,
    TileE: fx.Int64,
    TileR: fx.Int64,
    Total: fx.Int64,
    H: fx.Int64,
    Q: fx.Int64,
    QS: fx.Int64,
    R: fx.Constexpr[int],
    D: fx.Constexpr[int],
    I: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
    BM: fx.Constexpr[int],
    BN: fx.Constexpr[int],
    SORTED: fx.Constexpr[bool],
    PARTS: fx.Constexpr[int],
    LDS: fx.Constexpr[bool],
    PF: fx.Constexpr[bool],
    FUSED_Q: fx.Constexpr[bool],
    QMAX: fx.Constexpr[bool],
    DIRECT: fx.Constexpr[bool],
    KSTEP: fx.Constexpr[int],
    WAVES: fx.Constexpr[int],
    ADDR_BITS: fx.Constexpr[bool],
    GROUP_M: fx.Constexpr[int],
    PINGPONG: fx.Constexpr[bool],
    DMA: fx.Constexpr[bool],
    ROW_PAD: fx.Constexpr[int],
    CACHE: fx.Constexpr[int],
    PACKED: fx.Constexpr[bool],
    ROW_MAJOR: fx.Constexpr[bool],
    QSHUFFLE: fx.Constexpr[bool],
    EPILOGUE_DPP: fx.Constexpr[bool],
    PIPE: fx.Constexpr[int],
    GATHER_FUSED: fx.Constexpr[int],
    REV: fx.Constexpr[int],
    NE: fx.Constexpr[int],
    DERIVE: fx.Constexpr[bool],
    TAIL: fx.Constexpr[int],
    SPACK: fx.Constexpr[bool],
):
    THREADS = WAVES * 64
    NR = BN // (WAVES * 16)
    pid = fx.Int32(fx.block_idx.x)
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    bound = fx.Int32(R * (I // BN))
    if fx.const_expr(DERIVE):
        assert not DIRECT
        bound, d_ordered, d_tile, d_e, d_rb, d_count, scan = _derive_tile(Counts, pid, lane, I // BN, NE, BM)
        # The first wave also writes the tile list that the second projection reads.
        if pid == 0:
            if tid < 64:
                t_prefix, t_lo, t_hi = scan
                if lane == 63:
                    _store(Total, 0, t_prefix)
                t_start = t_prefix - t_lo - t_hi
                for j in range(t_lo):
                    _store(TileE, t_start + fx.Int32(j), lane)
                    _store(TileR, t_start + fx.Int32(j), fx.Int32(j) * BM)
                for j in range(t_hi):
                    _store(TileE, t_start + t_lo + fx.Int32(j), lane + 64)
                    _store(TileR, t_start + t_lo + fx.Int32(j), fx.Int32(j) * BM)
    elif fx.const_expr(not DIRECT):
        bound = _load(Total, 0) * (I // BN)
    split = fx.Int32(fx.block_idx.y)
    smem = fx.SharedAllocator()
    # A fused fill keeps the scales in one row-major table, padded to spread its rows over the banks.
    BUF = BM * (16 if GATHER_FUSED else 20) * KSTEP
    SROW = D // 32 + 16
    if fx.const_expr(LDS):
        shared = fx.recast_iter(
            fx.Int32, smem.allocate(BUF * 4 * (2 if PINGPONG or PIPE else 1), alignment=16).peek().ptr
        )
    if fx.const_expr(GATHER_FUSED):
        stable = fx.recast_iter(fx.Uint8, smem.allocate(BM * SROW, alignment=16).peek().ptr)
        swords = fx.recast_iter(fx.Int32, stable)
    if fx.const_expr(FUSED_Q and BN // WAVES == 16):
        qshared = fx.recast_iter(
            fx.Float32, smem.allocate(BM * (WAVES if QMAX else BN + 4) * 4, alignment=16).peek().ptr
        )
    if fx.const_expr(QSHUFFLE):
        qbytes = fx.recast_iter(fx.Uint8, smem.allocate(BM * BN // 2, alignment=16).peek().ptr)
        qwords = fx.recast_iter(fx.Int32, qbytes)
    if pid < bound:
        if fx.const_expr(DERIVE):
            ordered, tile, e, rb, count = d_ordered, d_tile, d_e, d_rb, d_count
            nbase = ordered % (I // BN) * BN
        else:
            ordered = _chiplet_order(pid, bound)
            tile = ordered // (I // BN)
            nbase = ordered % (I // BN) * BN
            e = _load(TileE, tile)
            rb, count = fx.Int32(0), fx.Int32(1)
            if fx.const_expr(not DIRECT):
                rb = _load(TileR, tile)
                count = _load(Counts, e)
        if fx.const_expr(GROUP_M == 0):
            # One group spans an expert's contiguous row tiles, so consecutive workgroups read each weight panel.
            tiles = (count + BM - 1) // BM
            first_tile = tile - rb // BM
            position = ordered - first_tile * (I // BN)
            tile = first_tile + position % tiles
            rb = (position % tiles) * BM
            nbase = (position // tiles) * BN
        if fx.const_expr(GROUP_M > 1):
            # Transpose complete row-tile groups within one expert; an incomplete last group keeps its order.
            member = (rb // BM) % GROUP_M
            first_row = rb - member * BM
            if first_row + (GROUP_M - 1) * BM < count:
                local = member * (I // BN) + ordered % (I // BN)
                tile = tile - member + local % GROUP_M
                rb = first_row + (local % GROUP_M) * BM
                nbase = (local // GROUP_M) * BN
        # An expert's last row tile with at most 64 (TAIL bit 1) or 32 (bit 0) routed rows runs a copy of the tile body
        # for that many rows; tile layouts keep BM rows, and rows past a short copy's are padding no output reads.
        live = count - rb
        bounds = [BM] + [b for b, bit in ((64, 2), (32, 1)) if TAIL & bit and b < BM]
        # (copied rows, MFMA rows): with TAIL bit 2 each copy also runs a body 16 rows shorter, skipping padding MFMAs.
        pairs = [(b, b) for b in bounds]
        if fx.const_expr(TAIL & 4):
            pairs = [(b, m) for b in bounds for m in (b, b - 16)]
        for variant in fx.range_constexpr(len(pairs)):
            BMC, BMT = pairs[variant]
            lo = pairs[variant + 1][1] if variant + 1 < len(pairs) else 0
            hi = BMT if variant > 0 else 1 << 30
            if (live > lo) & (live <= hi):
                rows = []
                for mi in fx.range_constexpr(BMT // 16):
                    row = rb + mi * 16 + lane % 16
                    rid = fx.Int32(0)
                    if row < count:
                        rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                    rows.append(rid // TOPK)
                zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(BMT // 16 * NR * 2)]
                if fx.const_expr(PF):
                    zeros = zeros + _w1_operands(
                        W,
                        WS,
                        e,
                        nbase,
                        wave,
                        lane,
                        split * (D // 32 // PARTS) + lane // 16,
                        I,
                        D,
                        BN,
                        WAVES,
                        ADDR_BITS,
                        CACHE,
                        PACKED,
                    )
                DMA_A = (
                    PIPE
                    and GATHER_FUSED
                    and PIPE1_DMA
                    and ROW_MAJOR
                    and KSTEP == 2
                    and PARTS == 1
                    and BN // WAVES == 32
                    and PACKED
                )
                if fx.const_expr(PIPE):
                    if fx.const_expr(GATHER_FUSED):
                        assert ROW_PAD == 0
                        assert DMA_A or BMC == BMT
                        sources = _a_panel_sources(
                            Routes,
                            e,
                            rb,
                            count,
                            tid,
                            R,
                            D,
                            TOPK,
                            BMC,
                            KSTEP,
                            THREADS,
                            R // TOPK if DMA_A else 0,
                        )
                        table = _load_scale_table(
                            AS, Routes, e, rb, count, tid, R, D, TOPK, BMC, THREADS, SROW
                        )
                        if fx.const_expr(DMA_A):
                            # Bounded to the quantized input: a padded row's out-of-range copy reads zeros.
                            arsrc = rocdl.get_buffer_rsrc(
                                rocdl.make_buffer_ptr(
                                    _ptr(A, fx.Int32, 16), num_records_bytes=R // TOPK * (D // 2)
                                )
                            )
                            _dma_a_panel(arsrc, sources, fx.Int32(0), shared, fx.Int32(0), wave)
                        else:
                            first = _load_a_panel_fused(A, sources, fx.Int32(0))
                        _store_scale_table(swords, table)
                    else:
                        first = _load_a_panel(A, AS, tile, fx.Int32(0), tid, D, BMT, KSTEP, THREADS, ROW_PAD)
                    if fx.const_expr(not DMA_A):
                        # Fill the first LDS buffer; each iteration then fills the other one for the next K step.
                        _store_a_panel(shared, fx.Int32(0), first, BMT, KSTEP)
                        gpu.barrier()
                if fx.const_expr(DMA_A):
                    # The loop carries each step's slice-0 weights and scale words, issued during the previous step.
                    n0 = nbase + wave * (BN // WAVES) + lane % 16
                    CARRY = NR * 2 + 2
                    zeros = (
                        zeros
                        + _w1_slice(W, e, n0, lane, fx.Int32(0), I, D, NR, ADDR_BITS, CACHE)
                        + _w1_words(WS, e, n0, lane, fx.Int32(0), I, D)
                        + _w1_slice(W, e, n0, lane, fx.Int32(1), I, D, NR, ADDR_BITS, CACHE)
                    )
                for kk, state in range(0, D // 128 // PARTS, KSTEP, init=zeros):
                    lds_base = fx.Int32(0)
                    if fx.const_expr(PIPE):
                        lds_base = ((fx.Int32(kk) // KSTEP) & 1) * BUF
                        next_kk = (fx.Int32(kk) + KSTEP < D // 128).select(fx.Int32(kk) + KSTEP, fx.Int32(kk))
                    if fx.const_expr(DMA_A):
                        # The previous copy has landed (only CARRY newer loads may be outstanding); the other buffer is free.
                        rocdl.s_waitcnt(vmcnt=CARRY + NR * 2)
                        gpu.barrier()
                        rocdl.sched_barrier(0)
                        carry = state[BMT // 16 * NR * 2 :]
                        step_w = [carry[: NR * 2], carry[NR * 2 + 2 : NR * 2 + 2 + NR * 2]]
                        words = carry[NR * 2 : NR * 2 + 2]
                        rocdl.sched_barrier(0)
                        _dma_a_panel(arsrc, sources, next_kk, shared, BUF - lds_base, wave)
                        rocdl.sched_barrier(0)
                    elif fx.const_expr(SORTED and LDS):
                        if fx.const_expr(PINGPONG):
                            lds_base = ((fx.Int32(kk) // KSTEP) & 1) * (BMT * 20 * KSTEP)
                        else:
                            gpu.barrier()
                        for cp in fx.range_constexpr((BMT * 4 * KSTEP + THREADS - 1) // THREADS):
                            ix = tid + cp * THREADS
                            if ix < BMT * 4 * KSTEP:
                                gi = (tile * (D // 32) + fx.Int32(kk) * 4) * BM + ix
                                if fx.const_expr(ROW_PAD != 0):
                                    gi = (tile * (D // 32) + fx.Int32(kk) * 4 + ix // BMT) * (
                                        BM + ROW_PAD
                                    ) + ix % BMT
                                if fx.const_expr(DMA):
                                    _load4_lds(
                                        A,
                                        gi * 4,
                                        fx.add_offset(shared, lds_base + (wave * 64 + cp * THREADS) * 4),
                                    )
                                    ss = fx.Int32(_load(AS, gi, fx.Uint8))
                                    fx.ptr_store(ss, fx.add_offset(shared, lds_base + BMT * 16 * KSTEP + ix))
                                else:
                                    vv = _load4(A, gi * 4)
                                    ss = fx.Int32(_load(AS, gi, fx.Uint8))
                                    fx.ptr_store(vv, fx.add_offset(shared, lds_base + ix * 4))
                                    fx.ptr_store(ss, fx.add_offset(shared, lds_base + BMT * 16 * KSTEP + ix))
                        if fx.const_expr(DMA):
                            rocdl.s_waitcnt(vmcnt=0)
                        gpu.barrier()
                    accum = [fx.Vector(x) for x in state[: BMT // 16 * NR * 2]]
                    if fx.const_expr(PF):
                        current_w = state[BMT // 16 * NR * 2 :]
                    for ki in fx.range_constexpr(KSTEP):
                        kg = ((fx.Int32(kk) + ki) + split * (D // 128 // PARTS)) * 4 + lane // 16
                        if fx.const_expr(DMA_A):
                            if fx.const_expr(ki == 0):
                                frags = [(fk, mi) for fk in range(KSTEP) for mi in range(BMT // 16)]

                                def _afrag(f):
                                    fk, mi = frags[f]  # noqa: B023
                                    # Slot of (row mi*16 + lane%16, group fk*4 + lane//16) in the copy's lane order.
                                    slot = (
                                        ((lane % 16) // 8) * 64
                                        + ((fk * 4 + lane // 16 - lane % 8) & 7) * 8
                                        + lane % 8
                                        + (mi // 2) * 256
                                        + (mi % 2) * 128
                                    )
                                    srow = (mi * 16 + lane % 16) * SROW + (fx.Int32(kk) + fk) * 4 + lane // 16  # noqa: B023
                                    return (
                                        _lds_read(fx.add_offset(shared, lds_base + slot * 4), T.i32x4, 16),  # noqa: B023
                                        fx.Int32(fx.Uint8(_lds_read(fx.add_offset(stable, srow), T.i8, 1))),
                                    )

                                # One fragment's LDS reads run ahead of the MFMAs that consume the previous one.
                                cur = _afrag(0)
                                for f in fx.range_constexpr(len(frags)):
                                    fk, mi = frags[f]
                                    if fx.const_expr(f + 1 < len(frags)):
                                        nxt = _afrag(f + 1)
                                    av, asc = cur
                                    # Snake order over the fragment's four weight operands (as in stage 2).
                                    for nj in fx.range_constexpr(NR * 2):
                                        q = nj if f % 2 == 0 else NR * 2 - 1 - nj
                                        ni, h = q // 2, q % 2
                                        ai = (mi * NR + ni) * 2
                                        # Byte fk*2 + ni of the step's word: slice 1 reads the word shifted down 16 bits.
                                        sw = words if fk == 0 else high  # noqa: F821
                                        accum[ai + h] = _mfma_sel(
                                            av,
                                            fx.Vector(step_w[fk][ni * 2 + h]),
                                            accum[ai + h],
                                            asc,
                                            fx.Int32(sw[h]),
                                            ni,
                                        )
                                    rocdl.sched_barrier(0)
                                    if fx.const_expr(f == BMT // 16 - 1):
                                        # Slice 0's weights and the step's words are dead: the next step's take their registers.
                                        high = [fx.Int32(w) >> 16 for w in words]  # noqa: F841
                                        rocdl.sched_barrier(0)
                                        next_carry = _w1_slice(
                                            W, e, n0, lane, next_kk, I, D, NR, ADDR_BITS, CACHE
                                        ) + _w1_words(WS, e, n0, lane, next_kk, I, D)
                                        rocdl.sched_barrier(0)
                                    if fx.const_expr(f == len(frags) - 1):
                                        # The next step's slice-1 weights get a full step of lead, like slice 0's.
                                        rocdl.sched_barrier(0)
                                        next_s1 = _w1_slice(
                                            W, e, n0, lane, next_kk + 1, I, D, NR, ADDR_BITS, CACHE
                                        )
                                        rocdl.sched_barrier(0)
                                    if fx.const_expr(f + 1 < len(frags)):
                                        cur = nxt
                        elif fx.const_expr(ROW_MAJOR):
                            operands = _w1_operands(
                                W, WS, e, nbase, wave, lane, kg, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED
                            )
                            if fx.const_expr(PIPE and ki == PIPE - 1):
                                # Issue the next panel after this slice's weights: vmcnt retires in order.
                                if fx.const_expr(PIPE_SCHED):
                                    rocdl.sched_barrier(0)
                                if fx.const_expr(GATHER_FUSED):
                                    pending = _load_a_panel_fused(A, sources, next_kk)
                                else:
                                    pending = _load_a_panel(
                                        A, AS, tile, next_kk, tid, D, BMT, KSTEP, THREADS, ROW_PAD
                                    )
                                if fx.const_expr(PIPE_SCHED):
                                    rocdl.sched_barrier(0)
                            for mi in fx.range_constexpr(BMT // 16):
                                ix = (ki * 4 + lane // 16) * BMT + mi * 16 + lane % 16
                                av = fx.ptr_load(
                                    fx.add_offset(shared, lds_base + ix * 4), result_type=T.i32x4
                                )
                                if fx.const_expr(GATHER_FUSED):
                                    srow = (mi * 16 + lane % 16) * SROW + (fx.Int32(kk) + ki) * 4 + lane // 16
                                    asc = fx.Int32(fx.Uint8(fx.ptr_load(fx.add_offset(stable, srow))))
                                else:
                                    asc = fx.Int32(
                                        fx.ptr_load(fx.add_offset(shared, lds_base + BMT * 16 * KSTEP + ix))
                                    )
                                for ni in fx.range_constexpr(NR):
                                    ai = (mi * NR + ni) * 2
                                    accum[ai] = _mfma(
                                        av,
                                        fx.Vector(operands[ni * 4]),
                                        accum[ai],
                                        asc,
                                        fx.Int32(operands[ni * 4 + 2]),
                                    )
                                    accum[ai + 1] = _mfma(
                                        av,
                                        fx.Vector(operands[ni * 4 + 1]),
                                        accum[ai + 1],
                                        asc,
                                        fx.Int32(operands[ni * 4 + 3]),
                                    )
                        else:
                            if fx.const_expr(SORTED):
                                if fx.const_expr(LDS):
                                    indices = [
                                        (ki * 4 + lane // 16) * BMT + mi * 16 + lane % 16
                                        for mi in range(BMT // 16)
                                    ]
                                    av = [
                                        fx.ptr_load(
                                            fx.add_offset(shared, lds_base + indices[mi] * 4),
                                            result_type=T.i32x4,
                                        )
                                        for mi in range(BMT // 16)
                                    ]
                                    asc = [
                                        fx.Int32(
                                            fx.ptr_load(
                                                fx.add_offset(
                                                    shared, lds_base + BMT * 16 * KSTEP + indices[mi]
                                                )
                                            )
                                        )
                                        for mi in range(BMT // 16)
                                    ]
                                else:
                                    indices = [
                                        (tile * (D // 32) + kg) * (BM + ROW_PAD) + mi * 16 + lane % 16
                                        for mi in range(BMT // 16)
                                    ]
                                    av = [_load4(A, indices[mi] * 4) for mi in range(BMT // 16)]
                                    asc = [
                                        fx.Int32(_load(AS, indices[mi], fx.Uint8)) for mi in range(BMT // 16)
                                    ]
                            else:
                                av = [_load4(A, rows[mi] * (D // 8) + kg * 4) for mi in range(BMT // 16)]
                                asc = [
                                    fx.Int32(_load(AS, rows[mi] * (D // 32) + kg, fx.Uint8))
                                    for mi in range(BMT // 16)
                                ]
                            if fx.const_expr(PF):
                                nextkk = ((fx.Int32(kk) + ki) + 1 < D // 128 // PARTS).select(
                                    (fx.Int32(kk) + ki) + 1, (fx.Int32(kk) + ki)
                                )
                                next_w = _w1_operands(
                                    W,
                                    WS,
                                    e,
                                    nbase,
                                    wave,
                                    lane,
                                    (nextkk + split * (D // 128 // PARTS)) * 4 + lane // 16,
                                    I,
                                    D,
                                    BN,
                                    WAVES,
                                    ADDR_BITS,
                                    CACHE,
                                    PACKED,
                                )
                            for ni in fx.range_constexpr(NR):
                                n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
                                if fx.const_expr(PF):
                                    wi = ni * 4
                                    wg, wu = fx.Vector(current_w[wi]), fx.Vector(current_w[wi + 1])
                                    sg, su = fx.Int32(current_w[wi + 2]), fx.Int32(current_w[wi + 3])
                                else:
                                    wg = _load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE)
                                    wu = _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE)
                                    sg = _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED)
                                    su = _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)
                                for mi in fx.range_constexpr(BMT // 16):
                                    ai = (mi * (NR) + ni) * 2
                                    accum[ai] = _mfma(av[mi], wg, accum[ai], asc[mi], sg)
                                    accum[ai + 1] = _mfma(av[mi], wu, accum[ai + 1], asc[mi], su)
                        if fx.const_expr(PF):
                            current_w = next_w
                    if fx.const_expr(PIPE and not DMA_A):
                        if fx.const_expr(PIPE_SCHED):
                            rocdl.sched_barrier(0)
                        _store_a_panel(shared, BUF - lds_base, pending, BMT, KSTEP)
                        gpu.barrier()
                    if fx.const_expr(PF):
                        accum = accum + current_w
                    if fx.const_expr(DMA_A):
                        accum = accum + next_carry + next_s1
                    result = yield accum
                if fx.const_expr(DMA_A):
                    # The last step re-copies its own panel into the idle buffer; retire it before the epilogue.
                    rocdl.s_waitcnt(vmcnt=0)
                    gpu.barrier()
                if fx.const_expr(FUSED_Q and BN // WAVES == 16 and QMAX):
                    # BF16-rounded values stay in registers; adjacent waves exchange only half-group maxima.
                    values, maxima = [], []
                    for mi in fx.range_constexpr(BMT // 16):
                        gate, up = fx.Vector(result[mi * 2]), fx.Vector(result[mi * 2 + 1])
                        for j in fx.range_constexpr(4):
                            local_row = mi * 16 + lane // 16 * 4 + j
                            x = _silu_bf16(gate[j], up[j])
                            a = fx.absf(x)
                            a = _epilogue_reduce(a, EPILOGUE_DPP)
                            values.append(x)
                            maxima.append(a)
                            if lane % 16 == 0:
                                fx.ptr_store(a, fx.add_offset(qshared, local_row * WAVES + wave))
                    gpu.barrier()
                    for mi in fx.range_constexpr(BMT // 16):
                        for j in fx.range_constexpr(4):
                            local_row = mi * 16 + lane // 16 * 4 + j
                            row = rb + local_row
                            other = fx.Float32(
                                fx.ptr_load(fx.add_offset(qshared, local_row * WAVES + (wave ^ 1)))
                            )
                            a = _max(_max(maxima[mi * 4 + j], other), fx.Float32(1.0e-10))
                            bits = a.bitcast(fx.Int32)
                            exponent = (
                                ((bits >> 23) & 255)
                                - 2
                                + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                            )
                            scale = (exponent << 23).bitcast(fx.Float32)
                            x = values[mi * 4 + j]
                            y = fx.Float32(gpu.shuffle_xor(x, 1, 64))
                            q = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x, y, scale, 0))
                            kg = (nbase + wave * 16) // 32
                            dst = fx.Int32(0)
                            if fx.const_expr(SORTED):
                                dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                            else:
                                if row < count:
                                    rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                                    dst = rid * (I // 32) + kg
                            if fx.const_expr(SORTED) or row < count:
                                if lane % 2 == 0:
                                    _store(Q, dst * 16 + wave % 2 * 8 + lane % 16 // 2, q, fx.Uint8)
                                if lane % 16 == 0 and wave % 2 == 0:
                                    _store(QS, dst, exponent, fx.Uint8)
                elif fx.const_expr(FUSED_Q and BN // WAVES == 16):
                    # Each wave owns half of a 32-value MX group: exchange the BF16-rounded values through padded
                    # LDS, then quantize complete groups with 16 lanes per group.
                    for mi in fx.range_constexpr(BMT // 16):
                        gate, up = fx.Vector(result[mi * 2]), fx.Vector(result[mi * 2 + 1])
                        for j in fx.range_constexpr(4):
                            local_row = mi * 16 + lane // 16 * 4 + j
                            col = wave * 16 + lane % 16
                            x = _silu_bf16(gate[j], up[j])
                            fx.ptr_store(x, fx.add_offset(qshared, local_row * (BN + 4) + col))
                    gpu.barrier()
                    for cp in fx.range_constexpr(BMT * BN // (2 * THREADS)):
                        t = tid + cp * THREADS
                        local_row, col = t // (BN // 2), t % (BN // 2) * 2
                        row = rb + local_row
                        x0 = fx.Float32(fx.ptr_load(fx.add_offset(qshared, local_row * (BN + 4) + col)))
                        x1 = fx.Float32(fx.ptr_load(fx.add_offset(qshared, local_row * (BN + 4) + col + 1)))
                        a = _max(fx.absf(x0), fx.absf(x1))
                        a = _epilogue_reduce(a, EPILOGUE_DPP)
                        a = _max(a, fx.Float32(1.0e-10))
                        bits = a.bitcast(fx.Int32)
                        exponent = (
                            ((bits >> 23) & 255)
                            - 2
                            + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                        )
                        scale = (exponent << 23).bitcast(fx.Float32)
                        q = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                        kg = (nbase + col) // 32
                        dst = fx.Int32(0)
                        if fx.const_expr(SORTED):
                            dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                        else:
                            if row < count:
                                rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                                dst = rid * (I // 32) + kg
                        if fx.const_expr(SORTED) or row < count:
                            _store(Q, dst * 16 + col % 32 // 2, q, fx.Uint8)
                            if col % 32 == 0:
                                _store(QS, dst, exponent, fx.Uint8)
                elif fx.const_expr(FUSED_Q):
                    # Two adjacent 16-column fragments share one MXFP4 scale; a 16-lane subgroup owns a row's group.
                    for mi in fx.range_constexpr(BMT // 16):
                        for ni in fx.range_constexpr(BN // (WAVES * 32)):
                            ai = (mi * (NR) + ni * 2) * 2
                            gate0, up0 = fx.Vector(result[ai]), fx.Vector(result[ai + 1])
                            gate1, up1 = fx.Vector(result[ai + 2]), fx.Vector(result[ai + 3])
                            kg = (nbase + wave * (BN // WAVES)) // 32 + ni
                            for j in fx.range_constexpr(4):
                                local_row = mi * 16 + lane // 16 * 4 + j
                                row = rb + local_row
                                x0 = _silu_bf16(gate0[j], up0[j])
                                x1 = _silu_bf16(gate1[j], up1[j])
                                a = _max(fx.absf(x0), fx.absf(x1))
                                a = _epilogue_reduce(a, EPILOGUE_DPP)
                                a = _max(a, fx.Float32(1.0e-10))
                                bits = a.bitcast(fx.Int32)
                                exponent = (
                                    ((bits >> 23) & 255)
                                    - 2
                                    + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                                )
                                scale = (exponent << 23).bitcast(fx.Float32)
                                y0 = fx.Float32(gpu.shuffle_xor(x0, 1, 64))
                                y1 = fx.Float32(gpu.shuffle_xor(x1, 1, 64))
                                q0 = fx.Int32(
                                    rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, y0, scale, 0)
                                )
                                q1 = fx.Int32(
                                    rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x1, y1, scale, 0)
                                )
                                dst = fx.Int32(0)
                                if fx.const_expr(SORTED):
                                    dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                                else:
                                    if row < count:
                                        rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                                        dst = rid * (I // 32) + kg
                                if fx.const_expr(SORTED) or row < count:
                                    if lane % 2 == 0:
                                        if fx.const_expr(QSHUFFLE):
                                            local_kg = wave * (BN // WAVES // 32) + ni
                                            qoff = (local_kg * BMT + local_row) * 16 + lane % 16 // 2
                                            fx.ptr_store(fx.Uint8(q0), fx.add_offset(qbytes, qoff))
                                            fx.ptr_store(fx.Uint8(q1), fx.add_offset(qbytes, qoff + 8))
                                        else:
                                            _store(Q, dst * 16 + lane % 16 // 2, q0, fx.Uint8)
                                            _store(Q, dst * 16 + lane % 16 // 2 + 8, q1, fx.Uint8)
                                    if lane % 16 == 0:
                                        if fx.const_expr(SPACK):
                                            # Packed scale block: row r's scale at byte (r % 16) * 8 + r // 16.
                                            _store(
                                                QS,
                                                (tile * (I // 32) + kg) * 128
                                                + local_row % 16 * 8
                                                + local_row // 16,
                                                exponent,
                                                fx.Uint8,
                                            )
                                        else:
                                            _store(QS, dst, exponent, fx.Uint8)
                    if fx.const_expr(QSHUFFLE):
                        gpu.barrier()
                        for cp in fx.range_constexpr((BMT * (BN // 32) + THREADS - 1) // THREADS):
                            qi = tid + cp * THREADS
                            if qi < BMT * (BN // 32):
                                local_kg, local_row = qi // BMT, qi % BMT
                                dst = (tile * (I // 32) + nbase // 32 + local_kg) * (BM + ROW_PAD) + local_row
                                qv = fx.ptr_load(fx.add_offset(qwords, qi * 4), result_type=T.i32x4)
                                fx.ptr_store(qv, fx.add_offset(_ptr(Q, fx.Int32, 16), dst * 4))
                else:
                    for mi in fx.range_constexpr(BMT // 16):
                        for ni in fx.range_constexpr(NR):
                            ai = (mi * (NR) + ni) * 2
                            gate = fx.Vector(result[ai])
                            up = fx.Vector(result[ai + 1])
                            n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
                            for j in fx.range_constexpr(4):
                                row = rb + mi * 16 + lane // 16 * 4 + j
                                if row < count:
                                    rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                                    if fx.const_expr(PARTS > 1):
                                        _store(H, (split * 2) * R * I + rid * I + n, gate[j], fx.Float32)
                                        _store(H, (split * 2 + 1) * R * I + rid * I + n, up[j], fx.Float32)
                                    else:
                                        g = gate[j]
                                        exp_neg = fx.Float32(
                                            rocdl.exp2(
                                                T.f32,
                                                fx.Float32(-g * fx.Float32(1.4426950408889634)).ir_value(),
                                            )
                                        )
                                        inv = fx.Float32(
                                            rocdl.rcp(T.f32, fx.Float32(fx.Float32(1.0) + exp_neg).ir_value())
                                        )
                                        val = (g * inv) * up[j]
                                        _store(H, rid * I + n, val, fx.BFloat16)


@flyc.kernel
def _gemm1_split_fused(
    X: fx.Int64,
    A: fx.Int64,
    AS: fx.Int64,
    W: fx.Int64,
    WS: fx.Int64,
    Ids: fx.Int64,
    Q: fx.Int64,
    QS: fx.Int64,
    R: fx.Constexpr[int],
    D: fx.Constexpr[int],
    I: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
    BN: fx.Constexpr[int],
    ADDR_BITS: fx.Constexpr[bool],
    CACHE: fx.Constexpr[int],
    PACKED: fx.Constexpr[bool],
    LOCAL_A: fx.Constexpr[bool],
    LOCAL_VEC: fx.Constexpr[bool],
):
    # The two K partitions run on separate waves of one CTA, which owns both partial sums and whole groups.
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    split, nwave = wave // (BN // 16), wave % (BN // 16)
    ordered = _chiplet_order(fx.Int32(fx.block_idx.x), R * (I // BN))
    rid, nbase = ordered // (I // BN), ordered % (I // BN) * BN
    e = _load(Ids, rid)
    token = rid // TOPK
    n = nbase + nwave * 16 + lane % 16
    smem = fx.SharedAllocator()
    shared = fx.recast_iter(fx.Float32, smem.allocate(BN * 16, alignment=16).peek().ptr)
    if fx.const_expr(LOCAL_A):
        abytes = fx.recast_iter(fx.Uint8, smem.allocate(D // 2 + D // 32, alignment=16).peek().ptr)
        awords = fx.recast_iter(fx.Int32, abytes)
        if fx.const_expr(LOCAL_VEC):
            # Four adjacent lanes quantize a 32-value scale group, eight packed values per word.
            for cp in fx.range_constexpr((D // 8 + BN * 8 - 1) // (BN * 8)):
                t = tid + cp * (BN * 8)
                if t < D // 8:
                    packed, exponent = _quantize_eight(X, token * (D // 8) + t)
                    fx.ptr_store(packed, fx.add_offset(awords, t))
                    if t % 4 == 0:
                        fx.ptr_store(fx.Uint8(exponent), fx.add_offset(abytes, D // 2 + t // 4))
        else:
            for cp in fx.range_constexpr((D // 2 + BN * 8 - 1) // (BN * 8)):
                t = tid + cp * (BN * 8)
                if t < D // 2:
                    x0 = fx.Float32(_load(X, token * D + t * 2, fx.BFloat16))
                    x1 = fx.Float32(_load(X, token * D + t * 2 + 1, fx.BFloat16))
                    a = _max(fx.absf(x0), fx.absf(x1))
                    for step in fx.range_constexpr(4):
                        a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
                    a = _max(a, fx.Float32(1.0e-10))
                    bits = a.bitcast(fx.Int32)
                    exponent = (
                        ((bits >> 23) & 255)
                        - 2
                        + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                    )
                    scale = (exponent << 23).bitcast(fx.Float32)
                    packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                    fx.ptr_store(fx.Uint8(packed), fx.add_offset(abytes, t))
                    if t % 16 == 0:
                        fx.ptr_store(fx.Uint8(exponent), fx.add_offset(abytes, D // 2 + t // 16))
        gpu.barrier()
    zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(2)]
    for kk, state in range(0, D // 256, 1, init=zeros):
        kg = (fx.Int32(kk) + split * (D // 256)) * 4 + lane // 16
        if fx.const_expr(LOCAL_A):
            av = fx.ptr_load(fx.add_offset(awords, kg * 4), result_type=T.i32x4)
            asc = fx.Int32(fx.ptr_load(fx.add_offset(abytes, D // 2 + kg)))
        else:
            av = _load4(A, token * (D // 8) + kg * 4)
            asc = fx.Int32(_load(AS, token * (D // 32) + kg, fx.Uint8))
        wg = _load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE)
        wu = _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE)
        sg = _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED)
        su = _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)
        gate = _mfma(av, wg, fx.Vector(state[0]), asc, sg)
        up = _mfma(av, wu, fx.Vector(state[1]), asc, su)
        result = yield [gate, up]
    if lane < 16:
        gate, up = fx.Vector(result[0]), fx.Vector(result[1])
        local_col = nwave * 16 + lane
        fx.ptr_store(gate[0], fx.add_offset(shared, split * (2 * BN) + local_col))
        fx.ptr_store(up[0], fx.add_offset(shared, split * (2 * BN) + BN + local_col))
    gpu.barrier()
    if tid < BN // 2:
        col = tid * 2
        g0 = fx.Float32(fx.ptr_load(fx.add_offset(shared, col))) + fx.Float32(
            fx.ptr_load(fx.add_offset(shared, 2 * BN + col))
        )
        g1 = fx.Float32(fx.ptr_load(fx.add_offset(shared, col + 1))) + fx.Float32(
            fx.ptr_load(fx.add_offset(shared, 2 * BN + col + 1))
        )
        u0 = fx.Float32(fx.ptr_load(fx.add_offset(shared, BN + col))) + fx.Float32(
            fx.ptr_load(fx.add_offset(shared, 3 * BN + col))
        )
        u1 = fx.Float32(fx.ptr_load(fx.add_offset(shared, BN + col + 1))) + fx.Float32(
            fx.ptr_load(fx.add_offset(shared, 3 * BN + col + 1))
        )
        x0, x1 = _silu_bf16(g0, u0), _silu_bf16(g1, u1)
        a = _max(fx.absf(x0), fx.absf(x1))
        for step in fx.range_constexpr(4):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
        a = _max(a, fx.Float32(1.0e-10))
        bits = a.bitcast(fx.Int32)
        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
        scale = (exponent << 23).bitcast(fx.Float32)
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
        _store(Q, rid * (I // 2) + nbase // 2 + tid, packed, fx.Uint8)
        if tid % 16 == 0:
            _store(QS, rid * (I // 32) + nbase // 32 + tid // 16, exponent, fx.Uint8)


@flyc.kernel
def _gemm1_grouped_split_fused(
    A: fx.Int64,
    AS: fx.Int64,
    W: fx.Int64,
    WS: fx.Int64,
    Routes: fx.Int64,
    Counts: fx.Int64,
    TileE: fx.Int64,
    TileR: fx.Int64,
    Total: fx.Int64,
    Q: fx.Int64,
    QS: fx.Int64,
    R: fx.Constexpr[int],
    D: fx.Constexpr[int],
    I: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
    BN: fx.Constexpr[int],
    ADDR_BITS: fx.Constexpr[bool],
    CACHE: fx.Constexpr[int],
    PACKED: fx.Constexpr[bool],
):
    # Both K partitions of the expert's 16-row tile in one workgroup; only live rows reach the epilogue.
    BM = 16
    STRIDE = BN + 4
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    split, nwave = wave // (BN // 16), wave % (BN // 16)
    pid = fx.Int32(fx.block_idx.x)
    bound = _load(Total, 0) * (I // BN)
    shared = fx.recast_iter(
        fx.Float32, fx.SharedAllocator().allocate(4 * BM * STRIDE * 4, alignment=16).peek().ptr
    )
    if pid < bound:
        ordered = _chiplet_order(pid, bound)
        tile, nbase = ordered // (I // BN), ordered % (I // BN) * BN
        e = _load(TileE, tile)
        rb, count = _load(TileR, tile), _load(Counts, e)
        row = rb + lane % 16
        rid = fx.Int32(0)
        if row < count:
            rid = _load(Routes, e * R + row)
        token = rid // TOPK
        n = nbase + nwave * 16 + lane % 16
        zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(2)]
        for kk, state in range(0, D // 256, 1, init=zeros):
            kg = (fx.Int32(kk) + split * (D // 256)) * 4 + lane // 16
            av = _load4(A, token * (D // 8) + kg * 4)
            asc = fx.Int32(_load(AS, token * (D // 32) + kg, fx.Uint8))
            wg = _load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE)
            wu = _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE)
            sg = _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED)
            su = _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)
            gate = _mfma(av, wg, fx.Vector(state[0]), asc, sg)
            up = _mfma(av, wu, fx.Vector(state[1]), asc, su)
            result = yield [gate, up]
        gate, up = fx.Vector(result[0]), fx.Vector(result[1])
        for j in fx.range_constexpr(4):
            local_row = lane // 16 * 4 + j
            if rb + local_row < count:
                offset = (split * 2 * BM + local_row) * STRIDE + nwave * 16 + lane % 16
                fx.ptr_store(gate[j], fx.add_offset(shared, offset))
                fx.ptr_store(up[j], fx.add_offset(shared, offset + BM * STRIDE))
        gpu.barrier()
        for cp in fx.range_constexpr(BM // 16):
            t = tid + cp * (BN * 8)
            local_row, col = t // (BN // 2), t % (BN // 2) * 2
            if rb + local_row < count:
                offset = local_row * STRIDE + col
                g0 = fx.Float32(fx.ptr_load(fx.add_offset(shared, offset))) + fx.Float32(
                    fx.ptr_load(fx.add_offset(shared, 2 * BM * STRIDE + offset))
                )
                g1 = fx.Float32(fx.ptr_load(fx.add_offset(shared, offset + 1))) + fx.Float32(
                    fx.ptr_load(fx.add_offset(shared, 2 * BM * STRIDE + offset + 1))
                )
                u0 = fx.Float32(fx.ptr_load(fx.add_offset(shared, BM * STRIDE + offset))) + fx.Float32(
                    fx.ptr_load(fx.add_offset(shared, 3 * BM * STRIDE + offset))
                )
                u1 = fx.Float32(fx.ptr_load(fx.add_offset(shared, BM * STRIDE + offset + 1))) + fx.Float32(
                    fx.ptr_load(fx.add_offset(shared, 3 * BM * STRIDE + offset + 1))
                )
                x0, x1 = _silu_bf16(g0, u0), _silu_bf16(g1, u1)
                a = _max(fx.absf(x0), fx.absf(x1))
                for step in fx.range_constexpr(4):
                    a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
                a = _max(a, fx.Float32(1.0e-10))
                bits = a.bitcast(fx.Int32)
                exponent = (
                    ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                )
                scale = (exponent << 23).bitcast(fx.Float32)
                packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                out_rid = _load(Routes, e * R + rb + local_row)
                _store(Q, out_rid * (I // 2) + nbase // 2 + col // 2, packed, fx.Uint8)
                if col % 32 == 0:
                    _store(QS, out_rid * (I // 32) + nbase // 32 + col // 32, exponent, fx.Uint8)


@flyc.kernel
def _activate_split(
    H: fx.Int64, Q: fx.Int64, S: fx.Int64, TOTAL: fx.Constexpr[int], PARTS: fx.Constexpr[int]
):
    t = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if t < TOTAL // 2:
        g0, g1 = fx.Float32(0), fx.Float32(0)
        u0, u1 = fx.Float32(0), fx.Float32(0)
        for p in fx.range_constexpr(PARTS):
            g0 = g0 + _load(H, (p * 2) * TOTAL + t * 2, fx.Float32)
            g1 = g1 + _load(H, (p * 2) * TOTAL + t * 2 + 1, fx.Float32)
            u0 = u0 + _load(H, (p * 2 + 1) * TOTAL + t * 2, fx.Float32)
            u1 = u1 + _load(H, (p * 2 + 1) * TOTAL + t * 2 + 1, fx.Float32)
        e0 = fx.Float32(rocdl.exp2(T.f32, (-g0 * fx.Float32(1.4426950408889634)).ir_value()))
        e1 = fx.Float32(rocdl.exp2(T.f32, (-g1 * fx.Float32(1.4426950408889634)).ir_value()))
        r0 = fx.Float32(rocdl.rcp(T.f32, (fx.Float32(1) + e0).ir_value()))
        r1 = fx.Float32(rocdl.rcp(T.f32, (fx.Float32(1) + e1).ir_value()))
        x0 = fx.Float32(fx.BFloat16(g0 * r0 * u0))
        x1 = fx.Float32(fx.BFloat16(g1 * r1 * u1))
        a = _max(fx.absf(x0), fx.absf(x1))
        for step in fx.range_constexpr(4):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
        a = _max(a, fx.Float32(1.0e-10))
        bits = a.bitcast(fx.Int32)
        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
        scale = (exponent << 23).bitcast(fx.Float32)
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
        _store(Q, t, packed, fx.Uint8)
        if t % 16 == 0:
            _store(S, t // 16, exponent, fx.Uint8)


def _w2_ki(W, e, nbase, wave, lane, kk, ki, D, I, BN, WAVES=4, CACHE=0):
    kg = (kk + ki) * 4 + lane // 16
    return [
        _load4(
            W, _weight_offset(e, nbase + wave * (BN // WAVES) + ni * 16 + lane % 16, kg, D, I, True), CACHE
        )
        for ni in range(BN // (16 * WAVES))
    ]


def _w2_word(WS, e, nbase, wave, lane, kk, D, I, BN, WAVES=4, CACHE=0):
    # The packed scale word both K slices and both column fragments of a step share: byte ki*2 + ni.
    n = nbase + wave * (BN // WAVES) + lane % 16
    kg = kk * 4 + lane // 16
    offset = e * D * (I // 128) + (n >> 5) * (I // 256) * 64 + (kg >> 3) * 64 + (kg & 3) * 16 + (n & 15)
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(WS, fx.Int32, 4)))
    return fx.Int32(rocdl.raw_ptr_buffer_load(T.i32, rsrc, fx.Int32(offset) * 4, fx.Int32(0), CACHE))


@flyc.kernel
def _gemm2(
    A: fx.Int64,
    AS: fx.Int64,
    W: fx.Int64,
    WS: fx.Int64,
    Routes: fx.Int64,
    Counts: fx.Int64,
    TileE: fx.Int64,
    TileR: fx.Int64,
    Total: fx.Int64,
    P: fx.Int64,
    R: fx.Constexpr[int],
    D: fx.Constexpr[int],
    I: fx.Constexpr[int],
    BM: fx.Constexpr[int],
    BN: fx.Constexpr[int],
    SORTED: fx.Constexpr[bool],
    LDS: fx.Constexpr[bool],
    PF: fx.Constexpr[bool],
    BF16_P: fx.Constexpr[bool],
    FP8_P: fx.Constexpr[bool],
    DIRECT: fx.Constexpr[bool],
    KSTEP: fx.Constexpr[int],
    WIDE: fx.Constexpr[bool],
    ADDR_BITS: fx.Constexpr[bool],
    GROUP_M: fx.Constexpr[int],
    CSHUFFLE: fx.Constexpr[bool],
    ROW_PAD: fx.Constexpr[int],
    CACHE: fx.Constexpr[int],
    PACKED: fx.Constexpr[bool],
    ROW_MAJOR: fx.Constexpr[bool],
    PIPE2: fx.Constexpr[int],
    REV: fx.Constexpr[int],
    NE: fx.Constexpr[int],
    DERIVE: fx.Constexpr[bool],
    TAIL: fx.Constexpr[int],
    FP4_P: fx.Constexpr[bool],
    WAVES2: fx.Constexpr[int],
    SPACK: fx.Constexpr[bool],
    W2NT: fx.Constexpr[int],
):
    FRAG = 32 if WIDE else 16
    ELEMENTS = 16 if WIDE else 4
    NR = BN // (FRAG * WAVES2)
    THREADS = WAVES2 * 64
    KFACTOR = 2 if WIDE else 1
    EBYTES = 1 if FP8_P else (2 if BF16_P else 4)
    # MXFP4 rows: each wave's 32 columns are one scale group; byte b of a row's group holds columns b and 16 + b.
    # A routed row of P holds its D/2 data bytes, then its D/32 E8M0 scales.
    ROWB = BN // 2 if FP4_P else BN * EBYTES
    PROW = D // 2 + D // 32
    ESTRIDE = ROWB + 16
    ETYPE = fx.Uint8 if FP8_P or FP4_P else (fx.BFloat16 if BF16_P else fx.Float32)
    if fx.const_expr(FP4_P):
        assert PIPE2 and CSHUFFLE and not WIDE and NR == 2
    if fx.const_expr(WAVES2 != 4):
        assert FP4_P
    pid = fx.Int32(fx.block_idx.x)
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    bound = fx.Int32(R * (D // BN))
    if fx.const_expr(DERIVE):
        assert not DIRECT
        bound, d_ordered, d_tile, d_e, d_rb, d_count, _ = _derive_tile(Counts, pid, lane, D // BN, NE, BM)
    elif fx.const_expr(not DIRECT):
        bound = _load(Total, 0) * (D // BN)
    smem = fx.SharedAllocator()
    # A pipelined loop double-buffers byte-scaled slabs; the epilogue's shuffle reuses them after the loop.
    BUFW = BM * 16 * KSTEP + (KSTEP * 4 * 128 // 4 if SPACK else BM * KSTEP)
    if fx.const_expr(SPACK):
        assert PIPE2 and BM == 96 and KSTEP * 4 * 128 // 16 <= 64 * WAVES2
    if fx.const_expr(PIPE2):
        assert LDS and CSHUFFLE and SORTED and ROW_MAJOR and not WIDE and KSTEP == 2 and ROW_PAD == 0
        assert ADDR_BITS and PACKED and CACHE == 0 and (BM * 4 * KSTEP) % 256 == 0
        pptr = smem.allocate(max(2 * BUFW * 4, BM * ESTRIDE + BM * (BN // 32)), alignment=16).peek().ptr
        shared = fx.recast_iter(fx.Int32, pptr)
        sbytes = fx.recast_iter(fx.Uint8, pptr)
    elif fx.const_expr(LDS):
        shared = fx.recast_iter(fx.Int32, smem.allocate(BM * 4 * 20 * KSTEP, alignment=16).peek().ptr)
    if fx.const_expr(PIPE2):
        evalues = fx.recast_iter(ETYPE, pptr)
        ewords = fx.recast_iter(fx.Int32, pptr)
    elif fx.const_expr(CSHUFFLE):
        eptr = smem.allocate(BM * ESTRIDE, alignment=16).peek().ptr
        evalues = fx.recast_iter(ETYPE, eptr)
        ewords = fx.recast_iter(fx.Int32, eptr)
    if pid < bound:
        if fx.const_expr(DERIVE):
            ordered, tile, e, rb, count = d_ordered, d_tile, d_e, d_rb, d_count
            nbase = ordered % (D // BN) * BN
        else:
            ordered = _chiplet_order(pid, bound)
            tile = ordered // (D // BN)
            nbase = ordered % (D // BN) * BN
            e = _load(TileE, tile)
            rb, count = fx.Int32(0), fx.Int32(1)
            if fx.const_expr(not DIRECT):
                rb = _load(TileR, tile)
                count = _load(Counts, e)
        if fx.const_expr(GROUP_M == 0):
            tiles = (count + BM - 1) // BM
            first_tile = tile - rb // BM
            position = ordered - first_tile * (D // BN)
            tile = first_tile + position % tiles
            rb = (position % tiles) * BM
            nbase = (position // tiles) * BN
        if fx.const_expr(GROUP_M > 1):
            member = (rb // BM) % GROUP_M
            first_row = rb - member * BM
            if first_row + (GROUP_M - 1) * BM < count:
                local = member * (D // BN) + ordered % (D // BN)
                tile = tile - member + local % GROUP_M
                rb = first_row + (local % GROUP_M) * BM
                nbase = (local // GROUP_M) * BN
        # An expert's short last tile runs a copy of the tile body for its row count, as in stage 1.
        live = count - rb
        bounds = [BM] + [b for b, bit in ((64, 2), (32, 1)) if TAIL & bit and b < BM]
        if fx.const_expr(TAIL & 4):
            # Every 16-row length: an expert's last tile runs no all-padding fragment.
            bounds = list(range(BM, 0, -16))
        for variant in fx.range_constexpr(len(bounds)):
            BMT = bounds[variant]
            lo = bounds[variant + 1] if variant + 1 < len(bounds) else 0
            hi = BMT if variant > 0 else 1 << 30
            if (live > lo) & (live <= hi):
                rows = []
                for mi in fx.range_constexpr(BMT // FRAG):
                    row = rb + mi * FRAG + lane % FRAG
                    rid = fx.Int32(0)
                    if row < count:
                        rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                    rows.append(rid)
                zeros = [fx.Vector.filled(ELEMENTS, 0.0, fx.Float32) for _ in range(BMT // FRAG * NR)]
                if fx.const_expr(PF):
                    zeros = zeros + _w2_operands(
                        W, WS, e, nbase, wave, lane, lane // FRAG, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED
                    )
                NA = BMT // FRAG * NR
                if fx.const_expr(PIPE2):
                    # The next step's slab and weights are in flight while the MFMAs read the current ones.
                    # The epilogue's routed rows, loaded now so that the K loop hides their latency.
                    erids = []
                    for cp in fx.range_constexpr((BMT * ROWB + THREADS * 16 - 1) // (THREADS * 16)):
                        local_row = (tid + cp * THREADS) * 16 // ROWB
                        valid = (local_row < BMT) & (rb + local_row < count)
                        erids.append(_load(Routes, e * R + rb + valid.select(local_row, fx.Int32(0))))
                    # A step's slab: KSTEP * 4 scale groups of the tile's first BMT rows (16 bytes and one scale byte
                    # each), packed BMT rows per group in LDS; the tile's layout in memory keeps BM rows per group.
                    first = (tile * (I // 32)) * BM

                    def _slab_copy(fbase, sbase):
                        # The step's 16-byte chunks over the workgroup's threads; a partial last round runs on whole waves.
                        for cp in fx.range_constexpr((BMT * 4 * KSTEP + THREADS - 1) // THREADS):  # noqa: B023
                            ix = tid + cp * THREADS
                            if fx.const_expr(BMT != BM):  # noqa: B023
                                ix = (ix // BMT) * BM + ix % BMT  # noqa: B023
                            if fx.const_expr((cp + 1) * THREADS > BMT * 4 * KSTEP):  # noqa: B023
                                if tid < BMT * 4 * KSTEP - cp * THREADS:  # noqa: B023
                                    _load4_lds(
                                        A,
                                        (fbase + ix) * 4,
                                        fx.add_offset(shared, sbase + (wave * 64 + cp * THREADS) * 4),
                                    )
                            else:
                                _load4_lds(
                                    A,
                                    (fbase + ix) * 4,
                                    fx.add_offset(shared, sbase + (wave * 64 + cp * THREADS) * 4),
                                )

                    _slab_copy(first, fx.Int32(0))
                    if fx.const_expr(SPACK):
                        if tid < KSTEP * 4 * 128 // 16:
                            _load4_lds(
                                AS,
                                (tile * (I // 32) * 128 + tid * 16) // 4,
                                fx.add_offset(shared, BMT * 16 * KSTEP),
                            )
                    elif tid < BMT * KSTEP // 4:
                        sx = tid * 16
                        if fx.const_expr(BMT != BM):
                            sx = (sx // BMT) * BM + sx % BMT
                        _load4_lds(AS, (first + sx) // 4, fx.add_offset(shared, BMT * 16 * KSTEP))
                    # The loop carries each step's weights and scale word, issued during the previous step:
                    # [slice 0 fragments, word, slice 1 fragments], so the newest WCARRY loads are always the carried ones.
                    WCARRY = KSTEP * NR + 1
                    zero_k = fx.Int32(0)
                    zeros = (
                        zeros
                        + _w2_ki(W, e, nbase, wave, lane, zero_k, 0, D, I, BN, WAVES2, W2NT)
                        + [_w2_word(WS, e, nbase, wave, lane, zero_k, D, I, BN, WAVES2, W2NT)]
                        + _w2_ki(W, e, nbase, wave, lane, zero_k, 1, D, I, BN, WAVES2, W2NT)
                    )
                    for kk, state in range(0, I // 128, KSTEP, init=zeros):
                        base = ((fx.Int32(kk) // KSTEP) & 1) * BUFW
                        nbuf = BUFW - base
                        next_kk = (fx.Int32(kk) + KSTEP < I // 128).select(fx.Int32(kk) + KSTEP, fx.Int32(kk))
                        accum = [fx.Vector(x) for x in state[:NA]]
                        carry = state[NA:]
                        wk = [carry[:NR], carry[NR + 1 :]]
                        word = fx.Int32(carry[NR])
                        # This step's slab has landed (only carried weight loads may be outstanding); the other buffer is free.
                        rocdl.s_waitcnt(vmcnt=WCARRY)
                        gpu.barrier()
                        rocdl.sched_barrier(0)
                        nfirst = (tile * (I // 32) + next_kk * 4) * BM
                        _slab_copy(nfirst, nbuf)
                        if fx.const_expr(SPACK):
                            if tid < KSTEP * 4 * 128 // 16:
                                _load4_lds(
                                    AS,
                                    ((tile * (I // 32) + next_kk * 4) * 128 + tid * 16) // 4,
                                    fx.add_offset(shared, nbuf + BMT * 16 * KSTEP),
                                )
                        elif tid < BMT * KSTEP // 4:
                            sx = tid * 16
                            if fx.const_expr(BMT != BM):
                                sx = (sx // BMT) * BM + sx % BMT
                            _load4_lds(AS, (nfirst + sx) // 4, fx.add_offset(shared, nbuf + BMT * 16 * KSTEP))
                        rocdl.sched_barrier(0)
                        # The next step's weights and scale word: a full step of MFMAs hides their latency.
                        nk0 = _w2_ki(W, e, nbase, wave, lane, next_kk, 0, D, I, BN, WAVES2, W2NT)
                        nword = _w2_word(WS, e, nbase, wave, lane, next_kk, D, I, BN, WAVES2, W2NT)
                        nk1 = _w2_ki(W, e, nbase, wave, lane, next_kk, 1, D, I, BN, WAVES2, W2NT)
                        rocdl.sched_barrier(0)
                        frags = [(ki, mi) for ki in range(KSTEP) for mi in range(BMT // FRAG)]

                        def _frag(f):
                            ix = (frags[f][0] * 4 + lane // FRAG) * BMT + frags[f][1] * FRAG + lane % FRAG  # noqa: B023
                            if fx.const_expr(SPACK):
                                return (
                                    _lds_read(fx.add_offset(shared, base + ix * 4), T.i32x4, 16),  # noqa: B023
                                    fx.Int32(0),
                                )
                            return (
                                _lds_read(fx.add_offset(shared, base + ix * 4), T.i32x4, 16),  # noqa: B023
                                fx.Int32(
                                    fx.Uint8(
                                        _lds_read(
                                            fx.add_offset(sbytes, (base + BMT * 16 * KSTEP) * 4 + ix),  # noqa: B023
                                            T.i8,
                                            1,
                                        )
                                    )
                                ),
                            )

                        if fx.const_expr(SPACK):
                            # Each K slice's row-fragment scales: bytes 0-3 / 4-7 of one 8-byte read.
                            spairs = [
                                fx.Vector(
                                    _lds_read(
                                        fx.add_offset(
                                            sbytes,
                                            (base + BMT * 16 * KSTEP) * 4
                                            + ((ki * 4 + lane // 16) * 16 + lane % 16) * 8,
                                        ),
                                        T.vec(2, T.i32),
                                        8,
                                    )
                                )
                                for ki in range(KSTEP)
                            ]
                        cur = _frag(0)
                        for f in fx.range_constexpr(len(frags)):
                            ki, mi = frags[f]
                            if fx.const_expr(f + 1 < len(frags)):
                                nxt = _frag(f + 1)
                            av, asc = cur
                            # Snake order: consecutive fragments meet on the same weight operand, so fewer MFMA operands
                            # change from one MFMA to the next (accumulation order is unchanged).
                            for nj in fx.range_constexpr(NR):
                                ni = nj if f % 2 == 0 else NR - 1 - nj
                                ai = mi * NR + ni
                                if fx.const_expr(SPACK):
                                    accum[ai] = _mfma_sel2(
                                        av,
                                        fx.Vector(wk[ki][ni]),
                                        accum[ai],
                                        fx.Int32(spairs[ki][mi // 4]),
                                        mi % 4,
                                        word,
                                        ki * 2 + ni,
                                    )
                                else:
                                    accum[ai] = _mfma_sel(
                                        av, fx.Vector(wk[ki][ni]), accum[ai], asc, word, ki * 2 + ni
                                    )
                            rocdl.sched_barrier(0)
                            if fx.const_expr(f + 1 < len(frags)):
                                cur = nxt
                        result = yield accum + nk0 + [nword] + nk1
                    rocdl.s_waitcnt(vmcnt=0)
                    gpu.barrier()
                if fx.const_expr(not PIPE2):
                    for kk, state in range(0, I // 128, KSTEP, init=zeros):
                        if fx.const_expr(SORTED and LDS):
                            gpu.barrier()
                            for cp in fx.range_constexpr((BMT * 4 * KSTEP + 255) // 256):
                                ix = tid + cp * 256
                                if ix < BMT * 4 * KSTEP:
                                    gi = (tile * (I // 32) + fx.Int32(kk) * 4) * BM + ix
                                    if fx.const_expr(ROW_PAD != 0):
                                        gi = (tile * (I // 32) + fx.Int32(kk) * 4 + ix // BMT) * (
                                            BM + ROW_PAD
                                        ) + ix % BMT
                                    vv = _load4(A, gi * 4)
                                    ss = fx.Int32(_load(AS, gi, fx.Uint8))
                                    fx.ptr_store(vv, fx.add_offset(shared, ix * 4))
                                    fx.ptr_store(ss, fx.add_offset(shared, BMT * 16 * KSTEP + ix))
                            gpu.barrier()
                        accum = [fx.Vector(x) for x in state[: BMT // FRAG * NR]]
                        if fx.const_expr(PF):
                            current_w = state[BMT // FRAG * NR :]
                        for ki in fx.range_constexpr(KSTEP * KFACTOR):
                            kg = fx.Int32(kk) * 4 + ki * (4 // KFACTOR) + lane // FRAG
                            if fx.const_expr(ROW_MAJOR):
                                # Keep both weight fragments and stream one activation row fragment at a time.
                                operands = _w2_operands(
                                    W, WS, e, nbase, wave, lane, kg, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED
                                )
                                for mi in fx.range_constexpr(BMT // FRAG):
                                    ix = (ki * (4 // KFACTOR) + lane // FRAG) * BMT + mi * FRAG + lane % FRAG
                                    av = fx.ptr_load(fx.add_offset(shared, ix * 4), result_type=T.i32x4)
                                    asc = fx.Int32(fx.ptr_load(fx.add_offset(shared, BMT * 16 * KSTEP + ix)))
                                    for ni in fx.range_constexpr(NR):
                                        ai = mi * NR + ni
                                        accum[ai] = _mfma2(
                                            av,
                                            fx.Vector(operands[ni * 2]),
                                            accum[ai],
                                            asc,
                                            fx.Int32(operands[ni * 2 + 1]),
                                            WIDE,
                                        )
                            else:
                                if fx.const_expr(SORTED):
                                    if fx.const_expr(LDS):
                                        indices = [
                                            (ki * (4 // KFACTOR) + lane // FRAG) * BMT
                                            + mi * FRAG
                                            + lane % FRAG
                                            for mi in range(BMT // FRAG)
                                        ]
                                        av = [
                                            fx.ptr_load(
                                                fx.add_offset(shared, indices[mi] * 4), result_type=T.i32x4
                                            )
                                            for mi in range(BMT // FRAG)
                                        ]
                                        asc = [
                                            fx.Int32(
                                                fx.ptr_load(
                                                    fx.add_offset(shared, BMT * 16 * KSTEP + indices[mi])
                                                )
                                            )
                                            for mi in range(BMT // FRAG)
                                        ]
                                    else:
                                        indices = [
                                            (tile * (I // 32) + kg) * (BM + ROW_PAD) + mi * FRAG + lane % FRAG
                                            for mi in range(BMT // FRAG)
                                        ]
                                        av = [_load4(A, indices[mi] * 4) for mi in range(BMT // FRAG)]
                                        asc = [
                                            fx.Int32(_load(AS, indices[mi], fx.Uint8))
                                            for mi in range(BMT // FRAG)
                                        ]
                                else:
                                    av = [
                                        _load4(A, rows[mi] * (I // 8) + kg * 4) for mi in range(BMT // FRAG)
                                    ]
                                    asc = [
                                        fx.Int32(_load(AS, rows[mi] * (I // 32) + kg, fx.Uint8))
                                        for mi in range(BMT // FRAG)
                                    ]
                                if fx.const_expr(PF):
                                    nextkk = (fx.Int32(kk) * KFACTOR + ki + 1 < I // (128 // KFACTOR)).select(
                                        fx.Int32(kk) * KFACTOR + ki + 1, fx.Int32(kk) * KFACTOR + ki
                                    )
                                    next_w = _w2_operands(
                                        W,
                                        WS,
                                        e,
                                        nbase,
                                        wave,
                                        lane,
                                        nextkk * (4 // KFACTOR) + lane // FRAG,
                                        D,
                                        I,
                                        BN,
                                        FRAG,
                                        ADDR_BITS,
                                        CACHE,
                                        PACKED,
                                    )
                                for ni in fx.range_constexpr(NR):
                                    n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
                                    if fx.const_expr(PF):
                                        wi = ni * 2
                                        w, s = fx.Vector(current_w[wi]), fx.Int32(current_w[wi + 1])
                                    else:
                                        w = _load4(W, _weight_offset(e, n, kg, D, I, ADDR_BITS), CACHE)
                                        s = _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED)
                                    for mi in fx.range_constexpr(BMT // FRAG):
                                        ai = mi * (NR) + ni
                                        accum[ai] = _mfma2(av[mi], w, accum[ai], asc[mi], s, WIDE)
                            if fx.const_expr(PF):
                                current_w = next_w
                        if fx.const_expr(PF):
                            accum = accum + current_w
                        result = yield accum
                if fx.const_expr(BMT // FRAG * NR == 1 and not PF and not PIPE2):
                    result = [result]
                for mi in fx.range_constexpr(BMT // FRAG if FP4_P else 0):
                    acc0, acc1 = fx.Vector(result[mi * NR]), fx.Vector(result[mi * NR + 1])
                    for j in fx.range_constexpr(4):
                        local_row = mi * 16 + lane // 16 * 4 + j
                        x0, x1 = fx.Float32(acc0[j]), fx.Float32(acc1[j])
                        a = _epilogue_reduce(_max(fx.absf(x0), fx.absf(x1)), True)
                        a = _max(a, fx.Float32(1.0e-10))
                        bits = a.bitcast(fx.Int32)
                        exponent = (
                            ((bits >> 23) & 255)
                            - 2
                            + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                        )
                        scale = (exponent << 23).bitcast(fx.Float32)
                        q = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                        fx.ptr_store(
                            fx.Uint8(q), fx.add_offset(evalues, local_row * ESTRIDE + wave * 16 + lane % 16)
                        )
                        if lane % 16 == 0:
                            fx.ptr_store(
                                fx.Uint8(exponent),
                                fx.add_offset(evalues, BM * ESTRIDE + local_row * (BN // 32) + wave),
                            )
                for mi in fx.range_constexpr(0 if FP4_P else BMT // FRAG):
                    for ni in fx.range_constexpr(NR):
                        acc = fx.Vector(result[mi * (NR) + ni])
                        n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
                        for j in fx.range_constexpr(ELEMENTS):
                            row = rb + mi * FRAG + lane // FRAG * 4 + j
                            if fx.const_expr(WIDE):
                                # A wide fragment returns four groups of four rows.
                                row = rb + mi * FRAG + lane // FRAG * 4 + (j // 4) * 8 + j % 4
                            if fx.const_expr(CSHUFFLE):
                                ecol = wave * (BN // 4) + ni * FRAG + lane % FRAG
                                if fx.const_expr(FP8_P):
                                    epacked = fx.Int32(
                                        rocdl.cvt_pk_fp8_f32(T.i32, acc[j], acc[j], fx.Int32(0), False)
                                    )
                                    fx.ptr_store(
                                        fx.Uint8(epacked),
                                        fx.add_offset(evalues, (row - rb) * (ESTRIDE // EBYTES) + ecol),
                                    )
                                else:
                                    fx.ptr_store(
                                        ETYPE(acc[j]),
                                        fx.add_offset(evalues, (row - rb) * (ESTRIDE // EBYTES) + ecol),
                                    )
                            elif row < count:
                                rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                                if fx.const_expr(FP8_P):
                                    packed = fx.Int32(
                                        rocdl.cvt_pk_fp8_f32(T.i32, acc[j], acc[j], fx.Int32(0), False)
                                    )
                                    _store(P, rid * D + n, packed, fx.Uint8)
                                elif fx.const_expr(BF16_P):
                                    _store(P, rid * D + n, acc[j], fx.BFloat16)
                                else:
                                    _store(P, rid * D + n, acc[j], fx.Float32)
                if fx.const_expr(CSHUFFLE):
                    gpu.barrier()
                    for cp in fx.range_constexpr((BMT * ROWB + THREADS * 16 - 1) // (THREADS * 16)):
                        pos = (tid + cp * THREADS) * 16
                        local_row, local_col = pos // ROWB, pos % ROWB
                        if local_row < BMT and rb + local_row < count:
                            if fx.const_expr(PIPE2):
                                rid = erids[cp]
                            else:
                                rid = _routed_row(Routes, e * R + rb + local_row, tile, DIRECT)
                            v = fx.ptr_load(
                                fx.add_offset(ewords, (local_row * ESTRIDE + local_col) // 4),
                                result_type=T.i32x4,
                            )
                            if fx.const_expr(FP4_P):
                                fx.ptr_store(
                                    v,
                                    fx.add_offset(
                                        _ptr(P, fx.Int32, 16), (rid * PROW + nbase // 2 + local_col) // 4
                                    ),
                                )
                                if local_col == 0:
                                    for sw in fx.range_constexpr(BN // 128):
                                        sv = fx.ptr_load(
                                            fx.add_offset(
                                                ewords, (BM * ESTRIDE) // 4 + local_row * (BN // 128) + sw
                                            )
                                        )
                                        _store(P, (rid * PROW + D // 2 + nbase // 32) // 4 + sw, sv)
                            else:
                                fx.ptr_store(
                                    v,
                                    fx.add_offset(
                                        _ptr(P, fx.Int32, 16), ((rid * D + nbase) * EBYTES + local_col) // 4
                                    ),
                                )


@flyc.kernel
def _gemm2_route_reduce(
    A: fx.Int64,
    AS: fx.Int64,
    W: fx.Int64,
    WS: fx.Int64,
    Ids: fx.Int64,
    Weights: fx.Int64,
    Out: fx.Int64,
    D: fx.Constexpr[int],
    I: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
    BN: fx.Constexpr[int],
    ADDR_BITS: fx.Constexpr[bool],
    CACHE: fx.Constexpr[int],
    PACKED: fx.Constexpr[bool],
):
    # One wave per route keeps route parallelism; only the useful MFMA row is exchanged.
    tid = fx.Int32(fx.thread_idx.x)
    lane, route = tid % 64, tid // 64
    token = fx.Int32(fx.block_idx.y)
    nbase = _chiplet_order(fx.Int32(fx.block_idx.x), D // BN) * BN
    rid = token * TOPK + route
    e = _load(Ids, rid)
    shared = fx.recast_iter(fx.Float32, fx.SharedAllocator().allocate(TOPK * BN * 4, alignment=16).peek().ptr)
    zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(BN // 16)]
    for kk, state in range(0, I // 128, 1, init=zeros):
        kg = fx.Int32(kk) * 4 + lane // 16
        av = _load4(A, rid * (I // 8) + kg * 4)
        asc = fx.Int32(_load(AS, rid * (I // 32) + kg, fx.Uint8))
        accum = []
        for ni in fx.range_constexpr(BN // 16):
            n = nbase + ni * 16 + lane % 16
            w = _load4(W, _weight_offset(e, n, kg, D, I, ADDR_BITS), CACHE)
            s = _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED)
            accum.append(_mfma(av, w, fx.Vector(state[ni]), asc, s))
        result = yield accum
    if fx.const_expr(BN == 16):
        result = [result]
    if lane < 16:
        for ni in fx.range_constexpr(BN // 16):
            acc = fx.Vector(result[ni])
            fx.ptr_store(acc[0], fx.add_offset(shared, route * BN + ni * 16 + lane))
    gpu.barrier()
    if tid < BN:
        value = fx.Float32(0)
        for k in fx.range_constexpr(TOPK):
            projected = fx.Float32(fx.ptr_load(fx.add_offset(shared, k * BN + tid)))
            weight = _load(Weights, token * TOPK + k, fx.Float32)
            value = value + weight * projected
        _store(Out, token * D + nbase + tid, value, fx.BFloat16)


@flyc.kernel
def _reduce(
    P: fx.Int64,
    Weights: fx.Int64,
    Out: fx.Int64,
    M: fx.Constexpr[int],
    D: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
    BF16_P: fx.Constexpr[bool],
    FP8_P: fx.Constexpr[bool],
):
    x = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if x < M * D:
        token, n = x // D, x % D
        value = fx.Float32(0)
        for k in fx.range_constexpr(TOPK):
            weight = _load(Weights, token * TOPK + k, fx.Float32)
            if fx.const_expr(FP8_P):
                packed = fx.Int32(_load(P, (token * TOPK + k) * D + n, fx.Uint8))
                projected = fx.Float32(rocdl.cvt_f32_fp8(T.f32, packed.ir_value(), 0))
            elif fx.const_expr(BF16_P):
                projected = fx.Float32(_load(P, (token * TOPK + k) * D + n, fx.BFloat16))
            else:
                projected = _load(P, (token * TOPK + k) * D + n, fx.Float32)
            value = value + weight * projected
        _store(Out, x, value, fx.BFloat16)


@flyc.kernel
def _reduce_fp8x4(
    P: fx.Int64,
    Weights: fx.Int64,
    Out: fx.Int64,
    M: fx.Constexpr[int],
    D: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
):
    x = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if x < M * (D // 4):
        token, n = x // (D // 4), x % (D // 4)
        values = [fx.Float32(0) for _ in range(4)]
        for k in fx.range_constexpr(TOPK):
            weight = _load(Weights, token * TOPK + k, fx.Float32)
            packed = _load(P, (token * TOPK + k) * (D // 4) + n)
            for j in fx.range_constexpr(4):
                projected = fx.Float32(rocdl.cvt_f32_fp8(T.f32, packed.ir_value(), j))
                values[j] = values[j] + weight * projected
        output = fx.Vector.from_elements([fx.BFloat16(v) for v in values])
        fx.ptr_store(output, fx.add_offset(_ptr(Out, fx.BFloat16, 8), x * 4))


@flyc.kernel
def _reduce_fp4(
    P: fx.Int64,
    Weights: fx.Int64,
    Out: fx.Int64,
    M: fx.Constexpr[int],
    D: fx.Constexpr[int],
    TOPK: fx.Constexpr[int],
    WORDS: fx.Constexpr[int],
):
    # One thread per WORDS data words of a scale group: word q covers columns 4q..4q+3 and 16+4q..16+4q+3; each
    # route's words are decoded with its E8M0 scale and summed in slot order in FP32.
    PROW = D // 2 + D // 32
    PER = D // (8 * WORDS)
    x = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if x < M * PER:
        token, r = x // PER, x % PER
        g, q0 = r // (4 // WORDS), (r % (4 // WORDS)) * WORDS
        values = [fx.Float32(0) for _ in range(8 * WORDS)]
        rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(P, fx.Int32, 16)))
        for k in fx.range_constexpr(TOPK):
            row = token * TOPK + k
            weight = _load(Weights, row, fx.Float32)
            if fx.const_expr(WORDS == 1):
                words = [_load(P, (row * PROW + g * 16) // 4 + q0)]
            else:
                vec = fx.Vector(
                    rocdl.raw_ptr_buffer_load(
                        T.vec(WORDS, T.i32), rsrc, row * PROW + g * 16 + q0 * 4, fx.Int32(0), 0
                    )
                )
                words = [fx.Int32(vec[w]) for w in range(WORDS)]
            sbyte = fx.Int32(_load(P, row * PROW + D // 2 + g, fx.Uint8))
            scale = (sbyte << 23).bitcast(fx.Float32)
            for w in fx.range_constexpr(WORDS):
                for sel in fx.range_constexpr(4):
                    pair = fx.Vector(
                        rocdl.cvt_scalef32_pk_f32_fp4(T.f32x2, words[w].ir_value(), scale.ir_value(), sel)
                    )
                    values[w * 4 + sel] = values[w * 4 + sel] + weight * fx.Float32(pair[0])
                    values[(WORDS + w) * 4 + sel] = values[(WORDS + w) * 4 + sel] + weight * fx.Float32(
                        pair[1]
                    )
        base = token * D + g * 32 + q0 * 4
        for h in fx.range_constexpr(2):
            output = fx.Vector.from_elements(
                [fx.BFloat16(v) for v in values[h * WORDS * 4 : (h + 1) * WORDS * 4]]
            )
            fx.ptr_store(output, fx.add_offset(_ptr(Out, fx.BFloat16, 8 * WORDS), base + h * 16))


def _route_quant_unroll(M, D, waves):
    unroll = 6 if M >= 4096 else (3 if M >= 2048 else 1)
    while unroll > 1 and (M * D // 8) % (waves * 64 * unroll):
        unroll -= 1
    return unroll if (M * D // 8) % (waves * 64 * unroll) == 0 else 0


def build_moe_module(num_tokens, model_dim, inter_dim, num_experts, topk, cfg_m=None):
    M, D, I, E, K = num_tokens, model_dim, inter_dim, num_experts, topk
    R = M * K
    MC = M if cfg_m is None else cfg_m
    FUSED_TINY = _sweep_bool("FUSED_TINY", False) if 2 <= MC <= 4 else False
    # Simpler addresses alter LLVM's unrolling and register allocation.
    ADDR_BITS = _sweep_bool("ADDR_BITS", MC in (16, 64, 1024, 2048))
    ADDR_BITS2 = _sweep_bool("ADDR_BITS2", True)
    # Stream first-projection weights past the caches where an expert's rows reuse them little.
    cache128 = _sweep("CACHE1128", 2) if MC == 128 else 0
    cache256 = _sweep("CACHE1256", 2) if MC == 256 else cache128
    CACHE1 = _sweep("CACHE1", 2 if 2 <= MC <= 64 else cache256)
    if M == 256 and E == 65:
        # Here an expert's weight panel serves about one row tile: stream it.
        CACHE1 = 2
    CACHE2 = _sweep("CACHE2", 0)
    PACKED_SCALES1 = _sweep_bool("PACKED_SCALES1", True)
    PACKED_SCALES2 = _sweep_bool("PACKED_SCALES2", True)
    GROUP_M = _sweep("GROUP_M", 4 if MC >= 1024 else (2 if MC == 512 else 1))
    if MC in (1024, 2048):
        GROUP_M = _sweep("GROUP_M_LARGE", 3)
    if MC == 4096:
        GROUP_M = _sweep("GROUP_M4096", 9)
    # Here each expert's routes fill about six row tiles: one group spans an expert in both projections.
    GROUP_M1 = GROUP_M2 = 6 if (M, MC, E) == (4096, 2048, 65) else GROUP_M
    if E == 65 and MC == 2048:
        GROUP_M1 = GROUP_M2 = 0
    sorted32 = _sweep_bool("SORTED32", False) if MC == 32 else False
    bm32 = _sweep("BM32", 32 if sorted32 else 16) if MC == 32 else 16
    bm64 = _sweep("BM64", 32) if MC == 64 else 32
    bm128 = _sweep("BM128", 48) if MC == 128 else 32
    # A 96-row tile avoids reloading expert panels for short second tiles.
    bm256 = _sweep("BM256", 96) if MC == 256 else 64
    bm4096 = _sweep("BM4096", 128) if MC == 4096 else 128
    BM = _sweep(
        "BM",
        bm32
        if MC == 32
        else (
            bm64
            if MC == 64
            else (
                bm128
                if MC == 128
                else (
                    bm256
                    if MC == 256
                    else (16 if MC < 32 else (32 if MC <= 128 else (bm4096 if MC >= 4096 else 64)))
                )
            )
        ),
    )
    if MC in (1024, 2048):
        BM = _sweep("BM_LARGE", 96)
    if MC == 512:
        BM = _sweep("BM512", 96)
    if MC == 1024:
        BM = _sweep("BM1024", BM)
    if MC == 2048:
        BM = _sweep("BM2048", BM)
    BN = _sweep("BN", _sweep("BN4", 64) if MC == 4 else (64 if MC < 8 else 128))
    bn1_large = _sweep("BN14096", 128) if MC == 4096 else BN
    bn1_base = _sweep("BN14", BN) if MC == 4 else bn1_large
    bn1_small = _sweep("BN1_SMALL", bn1_base) if MC <= 8 else bn1_base
    if 128 <= MC <= 2048:
        bn1_small = _sweep("BN1_MID", 64 if MC == 128 else bn1_small)
    BN1 = _sweep("BN1", bn1_small)
    BN2 = _sweep("BN2", _sweep("BN24", BN) if MC == 4 else BN)
    gather_small = _sweep_bool("GATHER_SMALL", True) if 64 <= MC <= 128 else True
    SORTED = _sweep_bool("SORTED", (MC >= 64 and gather_small) or sorted32)
    GATHER_TRANSPOSE = _sweep_bool("GATHER_TRANSPOSE", MC >= 256) and SORTED and BM % 32 == 0 and D % 256 == 0
    ROW_PAD = _sweep("ROW_PAD", 0) if SORTED else 0
    direct4 = _sweep_bool("DIRECT4", False) if MC == 4 else False
    DIRECT = _sweep_bool("DIRECT", MC == 1 or direct4 or FUSED_TINY) and not SORTED
    # Two K partitions improve first-projection occupancy for tiny batches.
    PARTS = (
        _sweep(
            "SPLIT",
            _sweep("SPLIT1", 2)
            if MC == 1
            else (_sweep("SPLIT4", 2 if FUSED_TINY else 1) if MC == 4 else (2 if MC <= 2 else 1)),
        )
        if MC <= 32
        else 1
    )
    LDS = _sweep_bool("LDS", True) and SORTED
    PINGPONG1 = _sweep_bool("PINGPONG1", False) and LDS
    DMA1 = _sweep_bool("DMA1", False) and LDS
    pf128 = _sweep_bool("PF128", True) if MC == 128 else False
    PF = _sweep_bool("PF", (pf128 if MC == 128 else 64 <= MC < 128) or sorted32)
    pf1_large = _sweep_bool("PF14096", True) if MC == 4096 else PF
    if 128 <= MC <= 2048:
        pf1_large = _sweep_bool("PF1_MID", pf1_large)
    pf1_small = _sweep_bool("PF1_SMALL", False) if MC <= 8 else pf1_large
    PF1 = _sweep_bool("PF1", pf1_small)
    # Stage adjacent K slices together to amortize workgroup barriers.
    kstep128 = _sweep("KSTEP128", 2) if MC == 128 else 1
    kstep2048 = _sweep("KSTEP2048", 2) if MC == 2048 else kstep128
    KSTEP = _sweep("KSTEP", 2 if MC in (64, 256, 512, 1024, 4096) else kstep2048)
    KSTEP1 = _sweep("KSTEP1_DIRECT", 2 if MC == 32 else 1) if not LDS else KSTEP
    KSTEP1 = _sweep("KSTEP1", KSTEP1)
    KSTEP2 = KSTEP if LDS else 1
    mfma32_large = _sweep_bool("MFMA32_LARGE", False) if MC >= 1024 else False
    MFMA32 = (
        _sweep_bool("MFMA32", MC in (64, 256, 512) or mfma32_large)
        and SORTED
        and BM % 32 == 0
        and BN2 % 128 == 0
    )
    FUSED_Q = _sweep_bool("FUSED_Q", True) and PARTS == 1
    QMAX = (
        _sweep_bool("QMAX4", False) if MC == 4 else (_sweep_bool("QMAX4096", True) if MC == 4096 else False)
    )
    if MC in (8, 16):
        QMAX = _sweep_bool("QMAX_SMALL", False)
    if 128 <= MC <= 2048:
        # Paired waves exchange only group maxima: four floats of quantization LDS per row.
        QMAX = _sweep_bool("QMAX_MID", MC == 128 or QMAX)
    if MC == 2048:
        QMAX = _sweep_bool("QMAX2048", QMAX)
    waves1_small = (
        _sweep("WAVES1_SMALL", 8 if MC in (8, 16) else 4)
        if MC <= 32
        else (8 if MC == 4096 and BN1 >= 128 else 4)
    )
    if MC == 4:
        waves1_small = _sweep("WAVES14", waves1_small)
    if 128 <= MC <= 2048:
        waves1_small = _sweep("WAVES1_MID", waves1_small)
    WAVES1 = _sweep("WAVES1", waves1_small)
    if MC == 2048:
        WAVES1 = _sweep("WAVES12048", WAVES1)
    if MC == 4096:
        WAVES1 = _sweep("WAVES14096", 4)
    EPILOGUE_DPP = _sweep_bool("EPILOGUE_DPP", MC in (4, 64) or MC >= 256)
    QSHUFFLE = (
        _sweep_bool("QSHUFFLE", MC in (64, 256, 512, 1024, 2048, 4096))
        and SORTED
        and FUSED_Q
        and BN1 // WAVES1 >= 32
    )
    BF16_P = _sweep_bool("BF16_P", MC >= 128)
    FP8_P = _sweep_bool("FP8_P", MC in (16, 32, 64) or MC >= 128)
    FUSED_ROUTE_REDUCE = (
        (_sweep_bool("FUSED_ROUTE_REDUCE", MC == 1 or FUSED_TINY) if MC <= 4 else False)
        and not SORTED
        and not FP8_P
        and not BF16_P
    )
    REDUCE_BN = _sweep("REDUCE_BN", 16) if FUSED_ROUTE_REDUCE else 16
    FUSED_SPLIT1 = (
        (_sweep_bool("FUSED_SPLIT1", MC == 1 or FUSED_TINY) if MC <= 4 else False)
        and DIRECT
        and PARTS == 2
        and BN1 == 64
    )
    SPLIT_FUSED_BN = _sweep("SPLIT_FUSED_BN", 128) if FUSED_SPLIT1 else 128
    # The single input row fits in LDS and its quantization replaces a launch.
    FUSED_INPUT1 = _sweep_bool("FUSED_INPUT1", MC == 1 or FUSED_TINY) and FUSED_SPLIT1
    FUSED_INPUT_VEC = _sweep_bool("FUSED_INPUT_VEC", True) and FUSED_INPUT1 and D % 32 == 0
    FUSED_GROUP_SPLIT = (
        (_sweep_bool("FUSED_GROUP_SPLIT", True) if MC == 2 else False)
        and not SORTED
        and not DIRECT
        and PARTS == 2
        and BM == 16
        and BN1 == 64
        and WAVES1 == 4
    )
    GROUP_SPLIT_BN = _sweep("GROUP_SPLIT_BN", 64) if FUSED_GROUP_SPLIT else 64
    FP8_RESERVE = _sweep_bool("FP8_RESERVE", True) if MC <= 64 and FP8_P else False
    CSHUFFLE2 = _sweep_bool("CSHUFFLE2", True) and (FP8_P or _sweep_bool("CSHUFFLE_FP32", False))
    ROW_MAJOR1 = _sweep_bool("ROW_MAJOR1", MC >= 512) and LDS and not PF1
    # Prefetch the next activation panel into registers in the K step's last slice; double-buffer LDS.
    PIPE1 = (
        PIPE1_AT
        if (
            ROW_MAJOR1
            and E == 65
            and MC == 2048
            and not PINGPONG1
            and not DMA1
            and PARTS == 1
            and (BM * 4 * KSTEP1) % (WAVES1 * 64) == 0
        )
        else 0
    )
    # The pipelined fill reads the routed rows of the quantized input itself, in place of a gathered copy.
    GATHER_FUSED = (
        1 if (PIPE1 and ROW_PAD == 0 and WAVES1 == 4 and KSTEP1 == 2 and BM % 32 == 0 and D % 512 == 0) else 0
    )
    ROW_MAJOR2 = _sweep_bool("ROW_MAJOR2", MC >= 512) and LDS and not PF
    # Software-pipeline stage 2: next slab and weights in flight during the current step's MFMAs.
    PIPE2 = (
        1
        if (
            ROW_MAJOR2
            and E == 65
            and MC == 2048
            and KSTEP2 == 2
            and not MFMA32
            and CSHUFFLE2
            and ADDR_BITS2
            and PACKED_SCALES2
            and CACHE2 == 0
            and ROW_PAD == 0
            and BN2 == 128
        )
        else 0
    )
    # Both projections derive their tiles from the expert counts, which replaces the tile-list launch: nothing else
    # reads the list once the first projection fills its panels from the routed rows itself.
    DERIVE_TILES = bool(GATHER_FUSED and PIPE2 and SORTED and not DIRECT and E <= 128)
    # Short-tile copies of each projection's tile body (bit 1: 64 rows, bit 0: 32 rows). An output row depends on
    # its own activation row only, so a full tile may read padding rows a shorter stage-1 copy left unwritten.
    TAILS = DERIVE_TILES and BM == 96 and GROUP_M1 == 0 and GROUP_M2 == 0
    TAIL1 = (7 if M == 256 else 3) if TAILS else 0
    # Stage 2's 64-row copy too: an expert's last tile then reads only rows the first projection wrote.
    TAIL2 = 7 if TAILS else 0
    # Here each expert's W2 panel serves about one row tile: stream it past the caches.
    W2NT = 2 if (M == 256 and E == 65 and PIPE2) else 0
    BLOCK_ROUTE = _sweep_bool("BLOCK_ROUTE", True) if MC >= 256 else False
    EXPERT_ROUTE = _sweep_bool("EXPERT_ROUTE", MC in (1024, 4096))
    fused_route_small = _sweep_bool("FUSED_ROUTE_SMALL", False) if 2 <= MC <= 128 else False
    FUSED_ROUTE = _sweep_bool("FUSED_ROUTE", fused_route_small)
    ROUTE_WAVES = _sweep("ROUTE_WAVES", 16)
    quant_route_default = _sweep_bool("QUANT_ROUTE_MID", False) if 64 <= MC <= 128 else True
    QUANT_ROUTE = _sweep_bool("QUANT_ROUTE", quant_route_default) and not DIRECT if 2 <= MC <= 128 else False
    QUANT_EXPERT_ROUTE = (
        _sweep_bool("QUANT_EXPERT_ROUTE", MC >= 64) and not DIRECT and not QUANT_ROUTE and not FUSED_ROUTE
    )
    QUANT_VEC = _sweep_bool("QUANT_VEC", MC >= 1024) and D % 32 == 0
    ROUTE_TWO_PASS = _sweep_bool("ROUTE_TWO_PASS", MC >= 1024) and MC >= 64
    # Unroll the expert scans while each wave's segment stays within a few dozen id loads.
    UNROLL_SCAN = bool(ROUTE_TWO_PASS and (R + ROUTE_WAVES * 64 - 1) // (ROUTE_WAVES * 64) <= 48)
    # Separate scan and quantization workgroups; each quantizing thread keeps QUANT_UNROLL input loads in flight.
    QUANT_UNROLL = (
        _route_quant_unroll(M, D, ROUTE_WAVES)
        if (QUANT_EXPERT_ROUTE and QUANT_VEC and E == 65 and MC == 2048)
        else 0
    )
    FUSED_GATHER_TILES = (
        _sweep_bool("FUSED_GATHER_TILES", 64 <= MC <= 1024) and SORTED and not FUSED_ROUTE and not QUANT_ROUTE
    )
    max_tiles = (R + BM - 1) // BM + E
    if _sweep_bool("TIGHT_TILES", False):
        max_tiles = min(R, E + (R - E) // BM)
    if DIRECT:
        max_tiles = R
    p_dtype = torch.float8_e4m3fn if FP8_P else (torch.bfloat16 if BF16_P else torch.float32)
    # The pipelined stage 2 writes each route's row as MXFP4 with its E8M0 scales: half the bytes of FP8 rows.
    FP4_P = bool(PIPE2 and FP8_P)
    # Eight waves of 32 columns share one stage-2 tile: half the workgroups, each reading its routed activation
    # slab once for twice the columns.
    WAVES2 = 8 if FP4_P else 4
    # Stage 1 writes each tile's per-K-group scale block as 16 row slots of 8 bytes (byte i: row fragment i), so a
    # stage-2 lane reads all of a K slice's row-fragment scales with one 8-byte LDS read.
    SPACK = bool(FP4_P and BM == 96 and ROW_PAD == 0)
    BN2G = BN2 * WAVES2 // 4
    # Two data words per reduction thread: 16 outputs, an 8-byte load per route.
    RWORDS = 2

    def scratch(device):
        # Every buffer is written in the call before any read; nothing is kept across calls.
        aq = torch.empty((M, D // 2), device=device, dtype=torch.uint8)
        asc = torch.empty((M, D // 32), device=device, dtype=torch.uint8)
        counts = torch.empty(E, device=device, dtype=torch.int32)
        routes = torch.empty((E, R), device=device, dtype=torch.int32)
        te = torch.empty(max_tiles, device=device, dtype=torch.int32)
        tr = torch.empty(max_tiles, device=device, dtype=torch.int32)
        total = torch.empty(1, device=device, dtype=torch.int32)
        h = torch.empty((R, I), device=device, dtype=torch.bfloat16) if not FUSED_Q or PARTS > 1 else total
        hp = (
            torch.empty((PARTS, 2, R, I), device=device, dtype=torch.float32)
            if PARTS > 1 and not FUSED_GROUP_SPLIT
            else h
        )
        hq = (
            torch.empty((R, I // 2), device=device, dtype=torch.uint8)
            if not (SORTED and FUSED_Q and PARTS == 1)
            else total
        )
        hs = (
            torch.empty((R, I // 32), device=device, dtype=torch.uint8)
            if not (SORTED and FUSED_Q and PARTS == 1)
            else total
        )
        p = torch.empty((R, D * (4 if FP8_RESERVE else 1)), device=device, dtype=p_dtype)
        if FP4_P:
            p = torch.empty((R, D // 2 + D // 32), device=device, dtype=torch.uint8)
        aqg = (
            torch.empty((max_tiles, BM + ROW_PAD, D // 2), device=device, dtype=torch.uint8)
            if SORTED and not GATHER_FUSED
            else aq
        )
        asg = (
            torch.empty((max_tiles, BM + ROW_PAD, D // 32), device=device, dtype=torch.uint8)
            if SORTED and not GATHER_FUSED
            else asc
        )
        hqg = (
            torch.empty((max_tiles, BM + ROW_PAD, I // 2), device=device, dtype=torch.uint8) if SORTED else hq
        )
        hsg = (
            torch.empty((max_tiles, BM + ROW_PAD, I // 32), device=device, dtype=torch.uint8)
            if SORTED
            else hs
        )
        if SPACK:
            hsg = torch.empty((max_tiles, 128, I // 32), device=device, dtype=torch.uint8)
        return [aq, asc, counts, routes, te, tr, total, h, hq, hs, p, aqg, asg, hqg, hsg, hp]

    @flyc.jit
    def run(
        X: fx.Int64,
        W1: fx.Int64,
        W2: fx.Int64,
        Weights: fx.Int64,
        Ids: fx.Int64,
        S1: fx.Int64,
        S2: fx.Int64,
        AQ: fx.Int64,
        ASC: fx.Int64,
        Counts: fx.Int64,
        Routes: fx.Int64,
        TE: fx.Int64,
        TR: fx.Int64,
        Total: fx.Int64,
        H: fx.Int64,
        HQ: fx.Int64,
        HS: fx.Int64,
        P: fx.Int64,
        Out: fx.Int64,
        AQG: fx.Int64,
        ASG: fx.Int64,
        HQG: fx.Int64,
        HSG: fx.Int64,
        HP: fx.Int64,
        Enabled: fx.Int32,
        stream: fx.Stream,
    ):
        """Launch expert-local groups of row tiles sharing weight panels."""
        # flyc.compile makes one dry call with no input tensors; every real call sets Enabled to one.
        if Enabled != 0:
            if fx.const_expr(not QUANT_ROUTE and not QUANT_EXPERT_ROUTE and not FUSED_INPUT1):
                _quantize(X, AQ, ASC, Counts, M * D, E, not DIRECT).launch(
                    grid=((M * D // 2 + 255) // 256,), block=(256,), stream=stream
                )
            if fx.const_expr(QUANT_EXPERT_ROUTE):
                if fx.const_expr(QUANT_UNROLL > 0):
                    _route_expert(
                        Ids,
                        Counts,
                        Routes,
                        R,
                        ROUTE_WAVES,
                        X,
                        AQ,
                        ASC,
                        M * D,
                        E,
                        True,
                        QUANT_VEC,
                        ROUTE_TWO_PASS,
                        UNROLL_SCAN,
                        QUANT_UNROLL,
                    ).launch(
                        grid=(E + M * D // 8 // (ROUTE_WAVES * 64 * QUANT_UNROLL),),
                        block=(ROUTE_WAVES * 64,),
                        stream=stream,
                    )
                else:
                    _route_expert(
                        Ids,
                        Counts,
                        Routes,
                        R,
                        ROUTE_WAVES,
                        X,
                        AQ,
                        ASC,
                        M * D,
                        E,
                        True,
                        QUANT_VEC,
                        ROUTE_TWO_PASS,
                        UNROLL_SCAN,
                        0,
                    ).launch(
                        grid=(
                            max(
                                E,
                                (M * D // (8 if QUANT_VEC else 2) + ROUTE_WAVES * 64 - 1)
                                // (ROUTE_WAVES * 64),
                            ),
                        ),
                        block=(ROUTE_WAVES * 64,),
                        stream=stream,
                    )
            elif fx.const_expr(QUANT_ROUTE):
                _quantize_route_fused(
                    X, AQ, ASC, Ids, Counts, Routes, TE, TR, Total, M * D, R, E, BM, ROUTE_WAVES
                ).launch(
                    grid=((M * D // 2 + ROUTE_WAVES * 64 - 1) // (ROUTE_WAVES * 64),),
                    block=(ROUTE_WAVES * 64,),
                    stream=stream,
                )
            elif fx.const_expr(DIRECT):
                TE = Ids
            elif fx.const_expr(FUSED_ROUTE):
                _route_fused(Ids, Counts, Routes, TE, TR, Total, R, E, BM, ROUTE_WAVES).launch(
                    grid=(1,), block=(ROUTE_WAVES * 64,), stream=stream
                )
            elif fx.const_expr(EXPERT_ROUTE):
                _route_expert(
                    Ids,
                    Counts,
                    Routes,
                    R,
                    ROUTE_WAVES,
                    X,
                    AQ,
                    ASC,
                    M * D,
                    E,
                    False,
                    False,
                    ROUTE_TWO_PASS,
                    False,
                    0,
                ).launch(grid=(E,), block=(ROUTE_WAVES * 64,), stream=stream)
            elif fx.const_expr(BLOCK_ROUTE):
                _route_block(Ids, Counts, Routes, R).launch(
                    grid=((R + 255) // 256, E), block=(256,), stream=stream
                )
            else:
                _route(Ids, Counts, Routes, R).launch(grid=((R + 255) // 256, E), block=(256,), stream=stream)
            if fx.const_expr(
                not DIRECT
                and not FUSED_ROUTE
                and not QUANT_ROUTE
                and not FUSED_GATHER_TILES
                and not DERIVE_TILES
            ):
                _route_tiles(Counts, TE, TR, Total, E, BM).launch(grid=(1,), block=(64,), stream=stream)
            if fx.const_expr(SORTED and not GATHER_FUSED):
                if fx.const_expr(GATHER_TRANSPOSE):
                    _gather_quant_coalesced(
                        AQ,
                        ASC,
                        AQG,
                        ASG,
                        Routes,
                        Counts,
                        TE,
                        TR,
                        Total,
                        R,
                        D,
                        K,
                        BM,
                        ROW_PAD,
                        E,
                        FUSED_GATHER_TILES,
                    ).launch(grid=((BM * (D // 32) + 255) // 256, max_tiles), block=(256,), stream=stream)
                else:
                    _gather_quant(
                        AQ,
                        ASC,
                        AQG,
                        ASG,
                        Routes,
                        Counts,
                        TE,
                        TR,
                        Total,
                        R,
                        D,
                        K,
                        BM,
                        ROW_PAD,
                        E,
                        FUSED_GATHER_TILES,
                    ).launch(grid=((BM * (D // 32) + 255) // 256, max_tiles), block=(256,), stream=stream)
            A1, AS1 = AQG, ASG
            if fx.const_expr(GATHER_FUSED):
                A1, AS1 = AQ, ASC
            if fx.const_expr(FUSED_SPLIT1):
                _gemm1_split_fused(
                    X,
                    AQ,
                    ASC,
                    W1,
                    S1,
                    Ids,
                    HQ,
                    HS,
                    R,
                    D,
                    I,
                    K,
                    SPLIT_FUSED_BN,
                    ADDR_BITS,
                    CACHE1,
                    PACKED_SCALES1,
                    FUSED_INPUT1,
                    FUSED_INPUT_VEC,
                ).launch(grid=(R * (I // SPLIT_FUSED_BN),), block=(SPLIT_FUSED_BN * 8,), stream=stream)
            elif fx.const_expr(FUSED_GROUP_SPLIT):
                _gemm1_grouped_split_fused(
                    AQ,
                    ASC,
                    W1,
                    S1,
                    Routes,
                    Counts,
                    TE,
                    TR,
                    Total,
                    HQ,
                    HS,
                    R,
                    D,
                    I,
                    K,
                    GROUP_SPLIT_BN,
                    ADDR_BITS,
                    CACHE1,
                    PACKED_SCALES1,
                ).launch(
                    grid=(max_tiles * (I // GROUP_SPLIT_BN),), block=(GROUP_SPLIT_BN * 8,), stream=stream
                )
            else:
                _gemm1(
                    A1,
                    AS1,
                    W1,
                    S1,
                    Routes,
                    Counts,
                    TE,
                    TR,
                    Total,
                    HP,
                    HQG,
                    HSG,
                    R,
                    D,
                    I,
                    K,
                    BM,
                    BN1,
                    SORTED,
                    PARTS,
                    LDS,
                    PF1,
                    FUSED_Q,
                    QMAX,
                    DIRECT,
                    KSTEP1,
                    WAVES1,
                    ADDR_BITS,
                    GROUP_M1,
                    PINGPONG1,
                    DMA1,
                    ROW_PAD,
                    CACHE1,
                    PACKED_SCALES1,
                    ROW_MAJOR1,
                    QSHUFFLE,
                    EPILOGUE_DPP,
                    PIPE1,
                    GATHER_FUSED,
                    _GEMM1_REV,
                    E,
                    DERIVE_TILES,
                    TAIL1,
                    SPACK,
                ).launch(grid=(max_tiles * (I // BN1), PARTS), block=(WAVES1 * 64,), stream=stream)
            if fx.const_expr(FUSED_SPLIT1 or FUSED_GROUP_SPLIT):
                pass
            elif fx.const_expr(PARTS > 1):
                _activate_split(HP, HQ, HS, R * I, PARTS).launch(
                    grid=((R * I // 2 + 255) // 256,), block=(256,), stream=stream
                )
            elif fx.const_expr(not FUSED_Q):
                _quantize(H, HQ, HS, Counts, R * I, E, False).launch(
                    grid=((R * I // 2 + 255) // 256,), block=(256,), stream=stream
                )
            if fx.const_expr(SORTED and not FUSED_Q):
                _gather_quant(
                    HQ, HS, HQG, HSG, Routes, Counts, TE, TR, Total, R, I, 1, BM, ROW_PAD, E, False
                ).launch(grid=((BM * (I // 32) + 255) // 256, max_tiles), block=(256,), stream=stream)
            if fx.const_expr(FUSED_ROUTE_REDUCE):
                _gemm2_route_reduce(
                    HQ, HS, W2, S2, Ids, Weights, Out, D, I, K, REDUCE_BN, ADDR_BITS2, CACHE2, PACKED_SCALES2
                ).launch(grid=(D // REDUCE_BN, M), block=(K * 64,), stream=stream)
            else:
                _gemm2(
                    HQG,
                    HSG,
                    W2,
                    S2,
                    Routes,
                    Counts,
                    TE,
                    TR,
                    Total,
                    P,
                    R,
                    D,
                    I,
                    BM,
                    BN2G,
                    SORTED,
                    LDS,
                    PF,
                    BF16_P,
                    FP8_P,
                    DIRECT,
                    KSTEP2,
                    MFMA32,
                    ADDR_BITS2,
                    GROUP_M2,
                    CSHUFFLE2,
                    ROW_PAD,
                    CACHE2,
                    PACKED_SCALES2,
                    ROW_MAJOR2,
                    PIPE2,
                    _GEMM2_REV,
                    E,
                    False,
                    TAIL2,
                    FP4_P,
                    WAVES2,
                    SPACK,
                    W2NT,
                ).launch(grid=(max_tiles * (D // BN2G),), block=(WAVES2 * 64,), stream=stream)
            if fx.const_expr(FUSED_ROUTE_REDUCE):
                pass
            elif fx.const_expr(FP4_P):
                _reduce_fp4(P, Weights, Out, M, D, K, RWORDS).launch(
                    grid=((M * D // (8 * RWORDS) + 255) // 256,), block=(256,), stream=stream
                )
            elif fx.const_expr(FP8_P):
                _reduce_fp8x4(P, Weights, Out, M, D, K).launch(
                    grid=((M * D // 4 + 255) // 256,), block=(256,), stream=stream
                )
            else:
                _reduce(P, Weights, Out, M, D, K, BF16_P, FP8_P).launch(
                    grid=((M * D + 255) // 256,), block=(256,), stream=stream
                )

    # Stage 1 keeps three waves per SIMD with its short-tile copy beside the full tile body; every other kernel of
    # the module already fits that occupancy.
    hints = {"waves_per_eu": 3} if TAIL1 else {}
    compiled = flyc.compile[hints](run, *([0] * 7), *([0] * 11), 0, *([0] * 5), 0, fx.Stream(None))
    return compiled, scratch


# Per token count: (sort unit / tile_m, stage-1 kernel, stage-2 kernel, stage-1 fused output quant).
# A ``_fp4`` stage-1 kernel quantizes SiLU(gate)*up to MXFP4 with e8m0 scales in its epilogue; the
# metadata's ``fuse_quant`` must say so too, so that the two-stage driver skips the separate a2 quant.
_CONFIGS = {
    256: (
        64,
        "flydsl_moe1_afp4_wfp4_bf16_t64x128x256_w2_fp4",
        "flydsl_moe2_afp4_wfp4_bf16_t64x128x256_atomic_bnt2",
        "fp4",
    ),
}


def _frozen(meta, frozen):
    return frozen


@functools.cache
def _plan(n_tokens, topk, n_experts, model_dim, inter_dim, w_dtype, out_dtype, shuffled, device):
    import aiter
    import aiter.fused_moe as fm
    from aiter import ActivationType, QuantType, dtypes
    from aiter.fused_moe import GateMode

    meta = fm.get_2stage_cfgs(
        fm.get_padded_M(n_tokens),
        model_dim,
        inter_dim,
        n_experts,
        topk,
        out_dtype,
        dtypes.fp4x2,
        w_dtype,
        QuantType.per_1x32,
        True,
        ActivationType.Silu,
        False,
        0,
        0,
        shuffled,
        GateMode.SEPARATED,
        is_ep=False,
        has_stage2_bias=False,
        opus_weights_shuffled=shuffled,
        config_file=None,
    )
    if n_tokens in _CONFIGS:
        tile_m, kn1, kn2, fuse_quant = _CONFIGS[n_tokens]
        s1, s2 = meta.stage1, meta.stage2
        meta = dataclasses.replace(
            meta,
            stage1=functools.partial(s1.func, *s1.args, **{**s1.keywords, "kernelName": kn1}),
            stage2=functools.partial(s2.func, *s2.args, **{**s2.keywords, "kernelName": kn2}),
            block_m=tile_m,
            fuse_quant=fuse_quant,
        )
    block_m = int(meta.block_m)
    max_padded = int(n_tokens * topk + n_experts * block_m - topk)
    max_blocks = int((max_padded + block_m - 1) // block_m)
    ws_size = int(aiter.moe_sorting_opus_get_workspace_size(n_tokens, n_experts, topk, 0))
    return (
        functools.partial(_frozen, frozen=meta),
        block_m,
        max_padded,
        max_blocks,
        ws_size,
        aiter.moe_sorting_opus_fwd,
        fm.fused_moe_2stages,
        ActivationType.Silu,
        QuantType.per_1x32,
        GateMode.SEPARATED,
        dtypes.fp4x2,
    )


# Token count -> the batch size whose tuned constants ``build_moe_module`` applies: the owned pipeline's constants
# were chosen for a 33-expert layer, so a 65-expert batch takes those of the batch with the same routes per expert.
_OWNED = {256: 2048, 2048: 2048, 4096: 2048}


@functools.cache
def _owned(num_tokens, model_dim, inter_dim, num_experts, topk):
    return build_moe_module(num_tokens, model_dim, inter_dim, num_experts, topk, cfg_m=_OWNED[num_tokens])


def run(
    *,
    hidden_states,
    w1,
    w2,
    topk_weights,
    topk_ids,
    w1_scale,
    w2_scale,
    activation,
    quant_type,
    doweight_stage1,
    gate_mode,
    act_quant,
    expert_mask,
    beta,
    linear_beta,
    out_dtype,
    out,
):
    n_tokens, topk = topk_ids.shape
    n_experts, model_dim, inter_dim2 = w2.shape
    inter_dim = inter_dim2 * 2
    if n_tokens in _OWNED:
        compiled, scratch = _owned(n_tokens, model_dim, inter_dim, n_experts, topk)
        buffers = [x.data_ptr() for x in scratch(out.device)]
        args = [x.data_ptr() for x in (hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale)]
        compiled(
            *args, *buffers[:11], out.data_ptr(), *buffers[11:], 1, fx.Stream(torch.cuda.current_stream())
        )
        return
    shuffled = bool(getattr(w1, "is_shuffled", False) and getattr(w2, "is_shuffled", False))
    (
        transform,
        block_m,
        max_padded,
        max_blocks,
        ws_size,
        sort_fwd,
        two_stages,
        act_t,
        quant_t,
        gate_t,
        q_dtype_a,
    ) = _plan(n_tokens, topk, n_experts, model_dim, inter_dim, w1.dtype, out.dtype, shuffled, out.device)
    device = out.device
    sorted_ids = torch.empty(max_padded, dtype=torch.int32, device=device)
    sorted_weights = torch.empty(max_padded, dtype=torch.float32, device=device)
    sorted_expert_ids = torch.empty(max_blocks, dtype=torch.int32, device=device)
    num_valid_ids = torch.empty(2, dtype=torch.int32, device=device)
    workspace = torch.empty(ws_size, dtype=torch.uint8, device=device) if ws_size > 0 else None
    # The sort's last phase zeroes ``out``, the target of stage 2's atomics.
    sort_fwd(
        topk_ids,
        topk_weights,
        sorted_ids,
        sorted_weights,
        sorted_expert_ids,
        num_valid_ids,
        out,
        n_experts,
        block_m,
        None,
        None,
        workspace,
        0,
        None,
        None,
        None,
    )
    two_stages(
        hidden_states,
        w1,
        w2,
        topk,
        sorted_ids,
        sorted_weights,
        sorted_expert_ids,
        num_valid_ids,
        out,
        True,
        block_m,
        activation=act_t,
        quant_type=quant_t,
        doweight_stage1=False,
        q_dtype_a=q_dtype_a,
        q_dtype_w=w1.dtype,
        w1_scale=w1_scale,
        w2_scale=w2_scale,
        topk_ids=topk_ids,
        topk_weights=topk_weights,
        gate_mode=gate_t,
        _metadata_transform=transform,
    )
